/* A26 frozen manifest: dissemination–distinctiveness (80 headwords), hand-authored. */
'use strict';
(function(){
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x,type='meaning')=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:type,type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P=(w,origin,ctx,mistake,quiz)=>D(w,{etymology:E(origin,w),contexts:[ctx],mistakes:[mistake],quiz});
P('dissemination','dissemination 源自拉丁语 disseminare“播种、散布”，由 dis- 与 semen“种子”构成；现代常指信息、知识或种子的广泛传播。',C('dissemination.s1','科研传播','The university funded the dissemination of the climate study so that local planners could use its findings.','大学资助传播这项气候研究，让当地规划人员能够利用其发现。','The university funded the dissemination of the climate study / so that local planners / could use its findings.','dissemination of + 信息/研究；该名词通常作不可数用法。','研究结果被传给更广泛的使用者，符合 s1 的传播义。'),M('The journal delayed dissemination the findings to rural clinics.','The journal delayed dissemination of the findings to rural clinics.','dissemination 后接传播内容时通常用 of 引出；缺少介词。','collocation'),[Q('dissemination',1,1,'The dissemination of a safety notice is its?','wide circulation to the people who need it','private destruction before anyone sees it','conversion into a legal penalty','dissemination 指广泛传播信息。'),Q('dissemination',2,1,'A public-health team translates a guide into several languages and sends it to clinics. What are they supporting?','dissemination of the guide','concealment of the guide','withdrawal of the guide','译成多种语言并发给诊所是传播资料。'),Q('dissemination',3,1,'Complete the standard phrase: dissemination ___ research findings.','of','at','under','常见结构是 dissemination of + 被传播内容。','collocation'),Q('dissemination',4,1,'Which action most clearly improves dissemination?','making a report accessible to relevant communities','locking every copy in an unused room','removing the report from all catalogues','让相关群体能获取报告会扩大传播。')]);
P('dissenter','dissenter 由 dissent 加表示人的后缀 -er 构成；dissent 来自拉丁语 dissentire“意见不同”，由 dis- 与 sentire“感觉、想法”构成。',C('dissenter.s1','宗教与公共意见','The dissenter published a careful argument against the council decision, while acknowledging that most members supported it.','这位异议者发表了反对理事会决定的严谨论证，同时承认多数成员支持该决定。','The dissenter published a careful argument against the council decision / while acknowledging / that most members supported it.','dissenter 是表示持异议者的可数名词；against 引出反对对象。','此人明确表达不同意见，符合异议者义。'),M('The committee praised her as a dissenter because she agreed with every proposal without objection.','The committee praised her as a supporter because she agreed with every proposal without objection.','dissenter 指持异议的人；全盘赞同且不反对应称 supporter。'),[Q('dissenter',1,1,'A dissenter in a committee is someone who?','openly disagrees with the prevailing view','records the minutes without taking a position','is automatically the committee chair','dissenter 指持有或表达不同意见的人。'),Q('dissenter',2,1,'Which person is a dissenter on a proposed rule?','the member who argues that it should be rejected','the member who votes for it and gives no objection','the clerk who types the final version','提出反对理由的成员是异议者。'),Q('dissenter',3,1,'A historical account calls a writer a dissenter. What is central to that label?','the writer challenged an accepted belief or authority','the writer copied the accepted belief exactly','the writer refused to write anything','称 dissenter 的重点是挑战主流观点或权威。'),Q('dissenter',4,1,'Which verb naturally describes what a dissenter may do?','challenge a majority decision','endorse every majority decision','count the ballots silently','dissenter 可以 challenge 多数决定。')]);
P('dissentious','dissentious 由 dissent 加形容词后缀 -ious 构成，表示好争论或容易引起纷争；它较少见且常带贬义。',C('dissentious.s1','文学人物描写','The playwright gives the dissentious courtier a habit of challenging even the smallest compromise, keeping the council in constant argument.','剧作家把那位好争论的朝臣写成连最小的妥协也要反对，使议事会一直争执。','The playwright gives the dissentious courtier a habit / of challenging even the smallest compromise / keeping the council in constant argument.','dissentious 修饰 courtier；此词较书面、少见。','反复挑起分歧并阻碍妥协，体现好争论的贬义。'),M('The dissentious delegates resolved every dispute calmly and accepted each compromise without protest.','The conciliatory delegates resolved every dispute calmly and accepted each compromise without protest.','平和化解争端并接受妥协与 dissentious 的好争论义相反。'),[Q('dissentious',1,1,'A dissentious colleague is most likely to?','pick arguments and resist agreement','settle disagreements with ease','avoid expressing any view','dissentious 指爱争论、造成纷争。'),Q('dissentious',2,1,'Which meeting is best described as dissentious?','members turn each minor difference into a quarrel','members compare evidence and reach a compromise','members listen quietly to a report','小分歧不断升级成争吵体现 dissentious。'),Q('dissentious',3,1,'The word dissentious usually carries what tone?','critical or disapproving','strongly complimentary','purely mathematical','该词通常贬指好争论、制造纷争。','register'),Q('dissentious',4,1,'Which adjective is the clearest contrast to dissentious?','conciliatory','quarrelsome','contentious','conciliatory 表示促成和解，与好争论相反。')]);
P('dissimilar','dissimilar 由否定前缀 dis- 加 similar 构成；similar 经法语来自拉丁语 similis“相像的”，dissimilar 因而表示不相像、彼此不同。',C('dissimilar.s2','比较研究','Although both devices measure air quality, their sensors and calibration methods are dissimilar to one another.','尽管两台设备都测量空气质量，它们的传感器和校准方法彼此不同。','Although both devices measure air quality / their sensors and calibration methods / are dissimilar to one another.','dissimilar to + 比较对象；one another 强调彼此。','这里比较两台设备的技术特征，体现 s2 的相异义。'),M('The twins are dissimilar from each other in no respect; every feature is exactly alike.','The twins are similar to each other in every respect; every feature is exactly alike.','“每个特征都完全相同”与 dissimilar 矛盾，应改为 similar。'),[Q('dissimilar',1,1,'Two designs are dissimilar if they?','differ in important features','match in every detail','belong to the same production batch only','dissimilar 表示不相似或不同。'),Q('dissimilar',2,2,'Choose the standard comparison: “The samples are dissimilar ___ the original.”','to','with','from than','常见结构是 dissimilar to。','collocation'),Q('dissimilar',3,1,'A botanist finds two leaves dissimilar in shape but similar in color. What differs?','their shape','their color','their species name necessarily','句中明确指出差异在形状而非颜色。'),Q('dissimilar',4,2,'Which statement best shows the idea of dissimilarity?','one plan relies on buses while the other depends on rail','both plans use the same route and timetable','the plans differ only in the date printed on the cover','交通方案依赖不同方式，构成实质差异。')]);
P('dissimulate','dissimulate 源自拉丁语 dissimulare“隐藏、伪装”，可追溯到 dis- 与 simulare“使相像”；动词指掩饰真实感受或意图。',C('dissimulate.s1','政治与谈判','During the interview, the envoy tried to dissimulate her alarm, but her hurried glance at the exit betrayed her.','采访中使节试图掩饰惊慌，但她匆忙瞥向出口的动作出卖了她。','During the interview / the envoy tried to dissimulate her alarm / but her hurried glance at the exit betrayed her.','dissimulate + 情绪/意图作宾语；try to 后接动词原形。','她隐藏真实惊慌却被行为暴露，符合掩饰义。'),M('He dissimulated his anger by announcing it openly to everyone in the room.','He expressed his anger by announcing it openly to everyone in the room.','公开宣布情绪是表达而非掩饰。'),[Q('dissimulate',1,1,'To dissimulate a fear is to?','hide or conceal that fear','make the fear stronger','measure the fear precisely','dissimulate 表示掩饰、不露出真实感受。'),Q('dissimulate',2,1,'A negotiator dissimulates confidence when she?','acts calm while concealing her uncertainty','admits openly that she is uncertain','leaves the negotiation before speaking','掩饰不确定、表现镇定就是 dissimulate。'),Q('dissimulate',3,1,'Which sentence uses dissimulate accurately?','He dissimulated his disappointment with a practiced smile.','He dissimulated his luggage onto the train.','The rain dissimulated the dry pavement by drying it.','该词可接 disappointment 等情绪作宾语。'),Q('dissimulate',4,1,'Dissimulate is closest in meaning to?','conceal','confess','celebrate','conceal 是“掩藏”的近义词。')]);
P('dissipate','dissipate 源自拉丁语 dissipare“散开、驱散”；现代既可指雾或担忧逐渐消散，也可及物地指挥霍金钱或精力。',C('dissipate.s2','个人理财','He dissipated the inheritance on speculative bets instead of keeping enough to pay the mortgage.','他把继承来的钱挥霍在投机赌注上，没有留下足够的钱还房贷。','He dissipated the inheritance on speculative bets / instead of keeping enough / to pay the mortgage.','dissipate + 金钱/精力表示挥霍；on + 用途。','继承款被耗尽在高风险投注上，符合 s2 的挥霍义。'),M('She dissipated her savings by placing them untouched in a secure account for retirement.','She preserved her savings by placing them untouched in a secure account for retirement.','把钱安全存起是保留储蓄，不是挥霍。'),[Q('dissipate',1,1,'If a mist dissipates, it?','gradually disappears or spreads away','becomes a solid wall','is stored in a sealed jar','雾 dissipate 指逐渐散去。'),Q('dissipate',2,2,'To dissipate a fortune is to?','waste it through careless spending','invest it prudently for later','receive it as a gift','此处及物义是挥霍财富。'),Q('dissipate',3,2,'Which sentence uses the financial sense?','She dissipated the grant on luxuries unrelated to the project.','The morning fog dissipated over the lake.','The crowd dissipated after the concert.','把拨款浪费在无关奢侈品上是挥霍。'),Q('dissipate',4,1,'A sharp rise in costs can dissipate a company reserve. What happens to the reserve?','it is wasted or used up','it becomes larger without spending','it changes into a new company','这里 dissipate 表示耗掉储备。')]);
P('dissipated','dissipated 是 dissipate 的过去分词形容词；用于人时可指沉溺享乐、生活放纵，也可按动词字面表示已经散去。',C('dissipated.s1','人物评价','The memoir portrays the once-wealthy heir as dissipated, spending nights gambling and neglecting every responsibility.','回忆录把这位昔日富有的继承人描写成放荡之人，夜夜赌博并荒废所有责任。','The memoir portrays the once-wealthy heir as dissipated / spending nights gambling / and neglecting every responsibility.','dissipated 作表语形容词，描述放纵生活方式；语气含批评。','赌博享乐、逃避责任构成放荡生活，符合 s1。'),M('The dissipated heir avoided gambling and devoted each evening to careful, moderate living.','The disciplined heir avoided gambling and devoted each evening to careful, moderate living.','节制、谨慎生活与 dissipated 的放纵义相反。'),[Q('dissipated',1,1,'A dissipated lifestyle is marked by?','excessive pleasure-seeking and lack of restraint','strict self-control and routine','careful saving and moderation','dissipated 描写放纵、沉溺享乐。'),Q('dissipated',2,2,'In “the smoke had dissipated,” dissipated means?','had gradually dispersed','had been stored safely','had become heavier','动词过去分词表示烟已经散去。'),Q('dissipated',3,1,'Which person could be called dissipated in the lifestyle sense?','someone who repeatedly spends nights in reckless excess','someone who follows a moderate routine','someone who gives up gambling and keeps commitments','长期放纵而不自制符合该形容词义。'),Q('dissipated',4,1,'What is the clearest contrast to a dissipated life?','a restrained and responsible life','a life of constant excess','a life devoted to reckless gambling','有节制且负责与放纵相反。')]);
P('dissolute','dissolute 源自拉丁语 dissolutus，是 dissolvere“松开、解散”的过去分词；形容沉溺感官享乐、缺乏道德自制的人或生活。',C('dissolute.s1','文学评论','The novel depicts the dissolute prince as spending public money on gambling and extravagant parties while the city faces famine.','小说把这位放荡的王子写成在城中闹饥荒时仍用公款赌博、举办奢华宴会。','The novel depicts the dissolute prince / as spending public money on gambling and extravagant parties / while the city faces famine.','dissolute 修饰人物；depict A as doing 表示把 A 描绘为……。','沉溺赌博与奢宴且无节制，体现 dissolute 的放荡义。'),M('The dissolute prince refused excess, lived modestly, and carefully protected the public funds.','The conscientious prince refused excess, lived modestly, and carefully protected the public funds.','节俭克制与沉溺享乐相反，不能称 dissolute。'),[Q('dissolute',1,1,'A dissolute person is typically?','morally unrestrained and devoted to pleasure','carefully moderate in every habit','unable to understand written language','dissolute 指放荡、沉溺享乐而缺乏自制。'),Q('dissolute',2,1,'Which conduct best fits a dissolute reputation?','repeated reckless indulgence despite serious consequences','keeping a modest budget and meeting obligations','declining luxury to help others','不顾严重后果地放纵享乐最符合该义。'),Q('dissolute',3,1,'The word dissolute is usually?','disapproving','a neutral technical measurement','an expression of praise','该词含有明显贬义。','register'),Q('dissolute',4,1,'Which adjective is the strongest contrast to dissolute?','self-disciplined','debauched','unrestrained','self-disciplined 表示自律，与放荡相反。')]);
P('dissolution','dissolution 来自拉丁语 dissolutio，经由 dissolvere“松开、解散”；可指组织或关系解体，也可指物质溶解。',C('dissolution.s2','化学实验','The dissolution of the sugar crystals was faster in warm water, where stirring helped the solute disperse.','糖晶体在温水中溶解得更快，搅拌有助于溶质分散。','The dissolution of the sugar crystals was faster in warm water / where stirring helped the solute disperse.','dissolution of + 物质；化学义指进入溶液的过程。','糖晶体进入水中形成溶液，体现 s2 的溶解义。'),M('The dissolution of the salt left solid crystals completely unchanged at the bottom of the glass.','The suspension of the salt left solid crystals visible at the bottom of the glass.','晶体保持固态可见，表示未发生溶解；dissolution 与结果矛盾。'),[Q('dissolution',1,1,'The dissolution of a partnership is its?','formal ending or breakup','expansion into new branches','informal celebration','dissolution 的一义是正式解散或解体。'),Q('dissolution',2,2,'In chemistry, dissolution occurs when a substance?','dissolves into a liquid to form a solution','changes into a different element','freezes without mixing','化学义指物质溶解到液体中。'),Q('dissolution',3,1,'A court orders the dissolution of a company. What follows?','the company is formally brought to an end','the company is automatically enlarged','the company starts a new legal case only','法院命令解散公司，组织依法终止。'),Q('dissolution',4,2,'Which observation is evidence of dissolution rather than breakup of an organization?','salt crystals disappear into stirred water','a club votes to close permanently','a board is formally disbanded','晶体进入水中是物质溶解。')]);
P('dissolved','dissolved 是 dissolve 的过去式和过去分词；dissolve 源自拉丁语 dissolvere“松开、解开”，可描述物质溶解或机构正式解散。',C('dissolved.s2','政治与法律','The assembly was dissolved before the election, so its members could no longer vote on new bills.','议会在选举前被解散，因此议员不能再就新法案投票。','The assembly was dissolved before the election / so its members could no longer vote / on new bills.','dissolved 作被动语态过去分词；此处是机构解散义而非溶解。','议会终止运作，成员不再履职，符合 s2。'),M('The parliament was dissolved in water until it became a clear liquid.','The parliament was dissolved before the election and ceased to operate.','议会是组织，不会被溶解成液体；语境误用了物质溶解义。','word-choice'),[Q('dissolved',1,1,'If a tablet has dissolved in water, it has?','broken down into the liquid','been formally removed from office','turned into a metal tool','物质 dissolved 指进入液体并溶解。'),Q('dissolved',2,2,'If parliament was dissolved, it was?','formally ended before its members were replaced','mixed into a glass of water','made into a new chemical compound','机构被 dissolved 是正式解散。'),Q('dissolved',3,1,'Which sentence uses dissolved for a substance?','The powder dissolved completely in warm water.','The club dissolved its members into a new election.','The court dissolved the sugar by ending its term.','粉末溶入温水，属于物质义。'),Q('dissolved',4,2,'Which event best illustrates an organization being dissolved?','a committee is formally disbanded after its task ends','a lump of salt disappears in soup','ice melts in a drink','委员会结束任务后被正式撤销，体现组织义。')]);
P('distantly','distantly 由 distant 加副词后缀 -ly 构成；distant 经法语源自拉丁语 distantem，是 distare“相隔、站开”的形式，副词可表示距离遥远或关系疏远。',C('distantly.s1','家庭关系','Although the cousins lived in the same town, they were distantly related and had never met before the reunion.','尽管表亲住在同一座城里，他们只是远亲，团聚前从未见过面。','Although the cousins lived in the same town / they were distantly related / and had never met before the reunion.','distantly 修饰 related，构成 distantly related“远亲”。','血缘关系不近而且彼此陌生，符合疏远义。'),M('The two families are distantly related because they are siblings with the same parents.','The two families are closely related because the two people are siblings with the same parents.','同父母的兄弟姐妹关系亲近，不是 distantly related。'),[Q('distantly',1,1,'Two people who are distantly related are?','connected through a remote family link','parent and child','unrelated by any family connection','distantly related 表示血缘关系较远。'),Q('distantly',2,1,'A narrator says a friend smiled distantly. The manner suggests?','little warmth or emotional closeness','strong affection and intimacy','a precise physical measurement','distantly 也可形容冷淡疏远的态度。'),Q('distantly',3,1,'Complete the natural phrase: “They are ___ related.”','distantly','distant','distance','副词 distantly 修饰 related。','grammar'),Q('distantly',4,1,'Which pair is most likely distantly related?','two people sharing a great-great-grandparent','a mother and her child','identical twins','共同祖先越远，亲缘关系越疏远。')]);
P('distaste','distaste 由否定前缀 dis- 加 taste 构成，原义涉及令人不悦的“味道”，现多指对某事强烈不喜欢或厌恶。',C('distaste.s1','工作态度','Her distaste for office gossip was clear: she changed the subject whenever colleagues began discussing a private matter.','她对办公室流言很反感：同事一谈私人事情，她就转移话题。','Her distaste for office gossip was clear / she changed the subject / whenever colleagues began discussing a private matter.','distaste for + 事物；名词表示厌恶、不喜欢。','她刻意回避流言，表明对其反感。'),M('His distaste for cruelty made him enjoy watching animals being harmed.','His taste for cruelty made him enjoy watching animals being harmed.','享受残害动物体现残忍倾向，与 distaste（厌恶）相反。'),[Q('distaste',1,1,'A distaste for cruelty means?','a strong dislike of cruel acts','a wish to cause more cruelty','a neutral lack of information','distaste 表示厌恶或不喜欢。'),Q('distaste',2,1,'Which choice shows distaste for gossip?','changing the subject when private rumors begin','asking everyone to repeat the rumors','sharing the rumors publicly','主动转移话题说明不喜欢流言。'),Q('distaste',3,1,'Choose the standard preposition: “distaste ___ dishonesty.”','for','at','between','常见搭配是 distaste for。','collocation'),Q('distaste',4,1,'Distaste is closest to?','aversion','enthusiasm','approval','aversion 表示厌恶、反感。')]);
P('distasteful','distasteful 由 distaste 加 -ful 构成，字面为“令人产生厌恶的”；可描述行为令人反感，也可指食物味道不佳。',C('distasteful.s1','职业伦理','The manager rejected the distasteful joke because it mocked a trainee for reporting harassment.','经理拒绝了那个令人反感的笑话，因为它嘲笑一名举报骚扰的实习生。','The manager rejected the distasteful joke / because it mocked a trainee / for reporting harassment.','distasteful 修饰 joke，评价行为令人厌恶或不适。','嘲笑举报骚扰者有失尊重，符合 s1 的令人反感义。'),M('The distasteful remark showed respect for the trainee and praised her courage without mocking anyone.','The respectful remark showed respect for the trainee and praised her courage without mocking anyone.','尊重并赞扬对方的言论并不令人反感。'),[Q('distasteful',1,1,'A distasteful comment is likely to be?','offensive or unpleasant','especially polite and considerate','impossible to hear','distasteful 可指令人反感、不愉快的。'),Q('distasteful',2,2,'A diner calls the soup distasteful. The diner means it?','tastes unpleasant','has an excellent flavor','is too cold to exist','食物语境中 distasteful 指味道难吃。'),Q('distasteful',3,1,'Which joke would a considerate editor call distasteful?','one that humiliates a victim for reporting abuse','one that makes a harmless pun about rain','one that celebrates a colleague’s achievement','羞辱举报者的笑话令人反感。'),Q('distasteful',4,1,'Which example uses the taste-related sense most directly?','The bitter sauce was distasteful to the child.','The apology was distasteful because it insulted the family.','The policy was distasteful to voters for ethical reasons.','句中直接说酱汁苦且令人难吃，是味道义。')]);
P('distend','distend 源自拉丁语 distendere“向不同方向拉伸”，由 dis- 与 tendere“伸展”构成；可不及物地胀大，也可及物地使空腔或容器扩张。',C('distend.s2','医疗观察','A buildup of gas can distend the abdomen, making the patient feel unusually tight and uncomfortable.','气体积聚会使腹部膨胀，让患者感到异常紧绷和不适。','A buildup of gas can distend the abdomen / making the patient feel unusually tight / and uncomfortable.','distend + 器官/容器作宾语是及物用法；此处对应 s2。','气体使腹部向外扩张，符合“使扩张”义。'),M('The surgeon distended the balloon by removing all the air and making it smaller.','The surgeon deflated the balloon by removing all the air and making it smaller.','抽走空气使气球缩小是 deflate，不是 distend。'),[Q('distend',1,1,'To distend a hollow organ is to?','make it swell or expand','remove its lining surgically','make it shrink completely','distend 指内部压力使其膨胀或使之扩张。'),Q('distend',2,2,'In “gas distended the abdomen,” the abdomen?','was made larger by internal pressure','became narrower as pressure fell','was separated from the body','此处是及物结构，气体使腹部扩张。'),Q('distend',3,1,'Which situation can cause a pipe to distend?','pressure inside pushes its walls outward','the pipe is emptied and compressed','its label is changed','内部压力增大可能使管壁向外膨胀。'),Q('distend',4,2,'A distended abdomen is one that is?','swollen or enlarged','perfectly flat and contracted','cut into separate pieces','distended 描写胀大、扩张。')]);
P('distent','distent 是较少见、偏技术性的形容词，源自拉丁语 distentus“被拉开的、胀大的”，为 distendere“扩张”的过去分词形式。',C('distent.s1','医学记录','The radiologist noted a distent section of bowel and requested follow-up imaging to determine why it had enlarged.','放射科医生记录了一段扩张的肠道，并要求进一步成像以查明其扩大的原因。','The radiologist noted a distent section of bowel / and requested follow-up imaging / to determine why it had enlarged.','distent 修饰 section，属罕见医学/正式用词；常见同义表达为 distended。','肠段明显扩大，对应 distent 的扩张义。'),M('The scan described the bowel as distent, meaning it had become unusually narrow and compressed.','The scan described the bowel as constricted, meaning it had become unusually narrow and compressed.','distent 是膨胀、扩张；狭窄压缩应使用 constricted。','word-choice'),[Q('distent',1,1,'A distent vessel is?','expanded or stretched','sealed permanently','made shorter by cutting','distent 源于“拉伸”，指扩张的。'),Q('distent',2,1,'In a medical report, distent most nearly means?','distended','infected','transparent','distent 与 distended 意义相近。'),Q('distent',3,1,'Which finding could accurately be called distent?','a hollow organ enlarged by pressure','a tube made narrower by compression','a bone that has healed without swelling','内部压力造成空腔器官扩大，符合 distent。'),Q('distent',4,1,'Distent is best classified as?','an uncommon formal or technical adjective','a common informal verb for walking','a plural noun for doctors','distent 是少见的正式形容词。','register')]);
P('distill','distill 源自拉丁语 distillare“滴下”，经法语进入英语；可指加热后冷凝液体以提纯，也可比喻提炼思想精华。',C('distill.s2','知识总结','The editor distilled a year of field notes into a concise guide that captured the findings most useful to new volunteers.','编辑把一年的实地笔记提炼成简明指南，保留了对新志愿者最有用的发现。','The editor distilled a year of field notes into a concise guide / that captured the findings / most useful to new volunteers.','distill A into B 表示把大量内容提炼成精华；过去式美式拼写为 distilled。','大量笔记被浓缩为核心要点，体现 s2 的思想提炼义。'),M('The editor distilled the report by adding every repeated detail until it became twice as long.','The editor expanded the report by adding every repeated detail until it became twice as long.','增加重复细节是在扩写，不是 distill 所指的提炼精华。','word-choice'),[Q('distill',1,1,'To distill a liquid in a laboratory is to?','heat it and condense its vapor to purify or separate it','freeze it without changing its composition','filter it through a dry paper label','蒸馏通过加热、冷凝蒸汽实现提纯或分离。'),Q('distill',2,2,'To distill an argument is to?','extract its central ideas from the details','add unrelated claims until it is longer','translate every sentence word for word','比喻义是从大量内容中提炼核心。'),Q('distill',3,2,'Which pattern naturally expresses the figurative sense?','distill years of research into a short summary','distill a summary out of into years','distill to research the years of a summary','常见搭配是 distill A into a summary。','collocation'),Q('distill',4,1,'A distiller separates a pure liquid from a mixture using?','heating and condensation','random sorting of written pages','freezing the glass container only','蒸馏的关键过程是汽化后冷凝。')]);
P('distillation','distillation 由 distill 加名词后缀 -ation 构成；distill 源自拉丁语 distillare“滴下”，名词既指蒸馏过程，也可比喻某内容的精华。',C('distillation.s2','写作与研究','Her lecture is a distillation of decades of fieldwork, reducing hundreds of observations to three clear principles.','她的讲座是数十年实地研究的精华，把数百条观察浓缩成三条清晰原则。','Her lecture is a distillation of decades of fieldwork / reducing hundreds of observations / to three clear principles.','a distillation of + 材料表示其提炼精华；此处为可数比喻义。','大量观察被浓缩为少数核心原则，符合 s2。'),M('The distillation of the report made it longer by restoring every discarded detail and repetition.','The expansion of the report made it longer by restoring every discarded detail and repetition.','恢复删去内容会扩写文本，与 distillation 的浓缩提炼义相反。','word-choice'),[Q('distillation',1,1,'In chemistry, distillation purifies a liquid by?','vaporizing it and condensing the vapor','adding a solid until it freezes','letting it evaporate without collecting anything','蒸馏把蒸汽冷凝收集以提纯。'),Q('distillation',2,2,'A distillation of a long book is?','a concise version containing its central ideas','a complete copy with every page duplicated','a list of all its printing errors','比喻义是提炼出的精华内容。'),Q('distillation',3,2,'Choose the natural expression: “The report is a distillation ___ the survey results.”','of','under','between','常见搭配是 a distillation of。','collocation'),Q('distillation',4,1,'Which example concerns the literal process?','separating liquids by heating and condensing vapors','summarizing ten interviews in one paragraph','extracting the main lesson from a novel','加热并冷凝分离液体是蒸馏过程。')]);
P('distinction','distinction 源自拉丁语 distinctio“区分、区别”，与 distinguere“分开、标记出”有关；可指差异，也可指卓越表现或荣誉。',C('distinction.s2','学术荣誉','She graduated with distinction after producing an original thesis and earning the highest marks in her cohort.','她凭借原创论文和年级最高分以优异成绩毕业。','She graduated with distinction / after producing an original thesis / and earning the highest marks in her cohort.','with distinction 是“以优异成绩/荣誉”固定搭配，对应 s2。','高分和原创成果带来荣誉，体现卓越义而非单纯区别。'),M('He graduated with distinction despite receiving the lowest marks and failing the final examination.','He graduated without distinction after receiving the lowest marks and failing the final examination.','最低分且未通过考试不支持“以优异成绩毕业”。'),[Q('distinction',1,1,'A distinction between two terms is?','a difference that separates their meanings','a prize awarded for excellent work','a copy that makes them identical','distinction 的 s1 指区别。'),Q('distinction',2,2,'To graduate with distinction means to?','achieve an honorably high standard','leave before completing the degree','receive a degree without assessment','with distinction 表示以优异成绩毕业。'),Q('distinction',3,2,'Which use expresses distinction as an honor?','The scientist received a distinction for her research.','The chart shows a distinction between red and blue.','The teacher explained the distinction in meaning.','获奖或荣誉体现 s2。'),Q('distinction',4,1,'A careful writer draws a distinction between evidence and opinion to?','show how the two differ','claim that both words are spelled alike','award a medal to each sentence','draw a distinction between 表示指出二者区别。')]);
P('distinctively','distinctively 由 distinctive 加副词后缀 -ly 构成；distinctive 与 distinct 同源于拉丁语 distinguere“区分、标出”，副词指以鲜明独特的方式。',C('distinctively.s1','品牌设计','The café is distinctively decorated with hand-painted blue tiles, so returning customers recognize it from the street.','这家咖啡馆以手绘蓝色瓷砖装饰，风格鲜明，老顾客从街上就能认出。','The café is distinctively decorated with hand-painted blue tiles / so returning customers / recognize it from the street.','distinctively 修饰 decorated，表示具有独特辨识度的方式。','特殊装饰使店铺容易识别，符合独特地、有特色地义。'),M('The café was distinctively decorated with the same plain white walls found in every neighboring shop.','The café was plainly decorated with the same white walls found in every neighboring shop.','与周边店铺完全相同的装饰并不鲜明独特。'),[Q('distinctively',1,1,'A distinctively shaped logo is?','easy to recognize because its form is unusual','identical to every competing logo','hidden where no one can see it','distinctively 表示以有辨识度的方式。'),Q('distinctively',2,1,'Which sentence uses distinctively naturally?','The singer speaks distinctively, with a recognizable regional accent.','The singer distinctively is yesterday before noon.','The singer placed distinctively the table under a window.','副词自然修饰 speaks，描述鲜明口音。'),Q('distinctively',3,1,'Complete the phrase: “a distinctively ___ pattern.”','colored','color','coloring','副词 distinctively 可修饰过去分词形容词 colored。','grammar'),Q('distinctively',4,1,'A building painted in a unique pattern stands out because it is painted?','distinctively','identically','invisibly','独特图案使建筑显得 distinctively painted。')]);
P('distinctiveness','distinctiveness 由 distinctive 加名词后缀 -ness 构成；其词族 distinct 可追溯到拉丁语 distinguere“区分”，此名词表示独特性或辨识度。',C('distinctiveness.s1','产品设计','The designer preserved the distinctiveness of the old radio by keeping its unusual dial while replacing the unreliable wiring.','设计师保留了老式收音机独特的表盘，同时更换了不可靠的线路。','The designer preserved the distinctiveness of the old radio / by keeping its unusual dial / while replacing the unreliable wiring.','distinctiveness of + 对象；preserve 表示保留其鲜明特征。','不寻常的表盘保留了产品可辨识的独特性。'),M('The brand gained distinctiveness by copying every shape and color used by its competitors.','The brand lost distinctiveness by copying every shape and color used by its competitors.','照搬竞争者设计会削弱品牌独特性，而不是增加它。','word-choice'),[Q('distinctiveness',1,1,'The distinctiveness of a symbol is its?','quality of being recognizable and unlike others','ability to match every other symbol','age measured in years','distinctiveness 指独特、易于辨认的性质。'),Q('distinctiveness',2,1,'A company wants its packaging to gain distinctiveness. It should?','develop recognizable features that competitors do not share','copy the market leader exactly','remove every visual feature','独有且可辨认的特征能提高 distinctiveness。'),Q('distinctiveness',3,1,'Which phrase is grammatically natural?','the distinctiveness of the design','the distinctive of the design','the distinctiveness for the design is','名词结构常用 distinctiveness of。','grammar'),Q('distinctiveness',4,1,'A clear accent and unusual rhythm can give a speaker?','distinctiveness','anonymity','uniformity','鲜明特征让说话者易被辨认。')]);
P('distinctly','distinctly 由 distinctive 加副词后缀 -ly 构成；distinct 与 distinguish 同源于拉丁语 distinguere“区分、标记出”，副词表示清楚地或显然地。',C('distinctly.s1','声音辨识','The bell rang distinctly above the traffic noise, so the crossing guard heard it from the corner.','铃声清晰地盖过交通噪声，因此路口警卫在街角也听得见。','The bell rang distinctly above the traffic noise / so the crossing guard / heard it from the corner.','distinctly 修饰 rang，表示听得清楚，对应 s1。','铃声能从背景声中分辨出来，体现清楚地。'),M('The bell rang distinctly because no listener could hear it above the traffic and everyone missed the signal.','The bell rang faintly because listeners could not hear it above the traffic.','若人人都没听见，就不能说铃声 distinctly 可辨。','context'),[Q('distinctly',1,1,'If a sound is heard distinctly, it is heard?','clearly and separately from other sounds','so faintly that it cannot be identified','only after it has stopped','distinctly 的 s1 表示清晰可辨地。'),Q('distinctly',2,2,'She was distinctly uncomfortable during the interview. This means she was?','obviously uncomfortable','slightly unsure whether she had arrived','completely relaxed','s2 可表示明显地、显然地。'),Q('distinctly',3,1,'Which phrase uses distinctly to mean clearly?','distinctly visible through the glass','distinctly absent from the room yesterday','distinct from the glass visibly','distinctly visible 表示清晰可见。'),Q('distinctly',4,2,'The word distinctly in “He was distinctly unhappy” means?','clearly or noticeably','in a separate physical room','with no difference at all','句中 distinctly 修饰 unhappy，意为明显地。')]);
P('distinguishable','distinguishable 由 distinguish 加形容词后缀 -able 构成；distinguish 经法语源自拉丁语 distinguere“分开、标记出”，此处指能够辨认或区分。',C('distinguishable.s1','数据分析','The two recordings were distinguishable because one contained a faint bell that was absent from the other.','两段录音能够区分，因为其中一段有微弱的铃声，另一段没有。','The two recordings were distinguishable / because one contained a faint bell / that was absent from the other.','distinguishable because 引出能够区分的依据。','铃声是可听辨的差异，符合可区别义。'),M('The twins were distinguishable because their faces, voices, and clothing were exactly identical.','The twins were indistinguishable because their faces, voices, and clothing were exactly identical.','特征完全一样使二者无法区分，应为 indistinguishable。','word-choice'),[Q('distinguishable',1,1,'Two sounds are distinguishable when listeners can?','tell one from the other','prove they were produced at the same time','make them equally loud','distinguishable 表示能够辨认或区分。'),Q('distinguishable',2,1,'Which detail makes two packages distinguishable?','one has a red label and the other has a blue label','both have the same label and shape','both are hidden from view','明显标签差异使包裹可区别。'),Q('distinguishable',3,1,'Complete the natural phrase: “The symptoms were distinguishable ___ those of a cold.”','from','at','under','常用结构为 distinguishable from。','collocation'),Q('distinguishable',4,1,'A tiny but audible click is still distinguishable if it can be?','detected as different from the background sound','confused with every other sound with certainty','removed from the recording automatically','能从背景声中听出差异即 distinguishable。')]);
P('distorted','distorted 是 distort 的过去分词形容词；distort 经法语源自拉丁语 distortus，与 torquere“扭转”有关，可指形状/信号变形，也可指事实被曲解。',C('distorted.s2','新闻核查','The headline presented a distorted account of the survey by quoting one respondent and omitting the views of everyone else.','标题只引用一名受访者并删去其他人的看法，歪曲了调查结果。','The headline presented a distorted account of the survey / by quoting one respondent / and omitting the views of everyone else.','distorted account/claim 表示被曲解的陈述，对应 s2。','选择性删引令调查意思失真，体现曲解义。'),M('The article gave a distorted account by quoting all responses fairly and preserving the full context.','The article gave an accurate account by quoting all responses fairly and preserving the full context.','公平引用并保留上下文是准确呈现，而非曲解。'),[Q('distorted',1,1,'A distorted image has?','an altered shape or appearance','the exact original proportions','no visible pixels','distorted 可指外观变形。'),Q('distorted',2,2,'A distorted quotation is one that?','misrepresents what the speaker meant','preserves the full context accurately','is printed in a large font','歪曲引语会错误呈现说话者本意。'),Q('distorted',3,1,'Which report is distorted?','one that removes a key qualification and reverses the claim','one that quotes the whole statement accurately','one that gives the date and source','删去关键限定后反转主张属于曲解。'),Q('distorted',4,1,'A speaker can distort evidence by?','selectively changing or presenting it so its meaning is misleading','checking each fact against the original record','including all relevant details','选择性处理证据会误导其含义。')]);
P('distortion','distortion 由 distort 加名词后缀 -ion 构成；distort 源自拉丁语 distortus，相关词根有“扭转”义，名词既指物理变形/失真，也指意义被曲解。',C('distortion.s2','法律论证','The lawyer objected to the distortion of her testimony, noting that the quotation omitted the sentence that limited her claim.','律师反对对其证词的曲解，并指出引文删去了限制其主张的那句话。','The lawyer objected to the distortion of her testimony / noting that the quotation omitted the sentence / that limited her claim.','distortion of + 信息/言论；此处是曲解义 s2。','删去限定语改变证词含义，体现误述、曲解。'),M('The distortion of the witness account preserved every qualification and represented the speaker exactly.','The accurate transcription of the witness account preserved every qualification and represented the speaker exactly.','逐字保留限定内容是准确记录，不是 distortion。'),[Q('distortion',1,1,'A distortion of a public statement is?','a misleading alteration of its meaning','a faithful copy of all its words','a pause between two speakers','distortion 可指对事实或话语的歪曲。'),Q('distortion',2,1,'In audio, distortion is heard when?','the signal is altered and sounds unclear or unnatural','the signal is reproduced perfectly','the volume is set to zero and no sound exists','音频失真指信号被改变而声音不自然。'),Q('distortion',3,2,'Which act creates a distortion of a witness statement?','quoting only half a sentence so the meaning changes','publishing the complete statement with context','checking the recording before quotation','断章取义导致证词被曲解。'),Q('distortion',4,1,'Which word can name either physical warping or misrepresentation?','distortion','distribution','distinction','distortion 有变形和曲解两义。')]);
P('distractor','distractor 由 distract 加表示施动者的 -or 构成；distract 源自拉丁语 distrahere“拉开、分散”，考试语境中 distractor 特指干扰性错误选项。',C('distractor.s1','考试命题','The distractor seemed plausible because it matched one keyword in the passage, but it contradicted the author’s conclusion.','这个干扰项看似合理，因为它对应了文章中的一个关键词，却与作者的结论矛盾。','The distractor seemed plausible / because it matched one keyword in the passage / but it contradicted the author’s conclusion.','distractor 是选择题中的可数名词；这里指错误选项。','选项利用关键词诱导但结论错误，正是干扰项作用。'),M('The answer key labeled the correct response as a distractor and marked all wrong choices as correct answers.','The answer key labeled the incorrect choices as distractors and marked the supported response as correct.','distractor 是错误干扰项，不能指有证据支持的正确答案。','word-choice'),[Q('distractor',1,1,'In a multiple-choice test, a distractor is?','an incorrect option designed to seem plausible','the instruction printed above the question','the official score for a student','distractor 指干扰性的错误选项。'),Q('distractor',2,1,'A strong distractor often?','reflects a likely misunderstanding','states the correct answer twice','has no connection to the question at all','好的干扰项对应常见误解，因此有迷惑性。'),Q('distractor',3,1,'A student rejects a distractor because it?','conflicts with evidence in the passage','matches every detail in the passage','is printed in a different typeface','与文章证据冲突的选项可以排除。'),Q('distractor',4,1,'Which item is a distractor in a quiz?','a tempting but incorrect answer choice','the correct answer supported by the text','the page number of the quiz','干扰项是看似可选但实际错误的答案。')]);
P('distressing','distressing 由 distress 加 -ing 构成；distress 经古法语 destresse 与拉丁语 districtia“困境、压迫”有关，形容令人痛苦或忧虑的事。',C('distressing.s1','突发事件','It was distressing to learn that the shelter had run out of medicine just before the storm reached the coast.','得知避难所恰在风暴抵达海岸前用完了药品，令人十分忧心。','It was distressing to learn / that the shelter had run out of medicine / just before the storm reached the coast.','It is distressing to learn that... 表示得知某事令人难过。','危急时刻缺药令人担忧，符合令人痛苦、不安义。'),M('The distressing news delighted every family because it confirmed that nobody had been hurt.','The reassuring news delighted every family because it confirmed that nobody had been hurt.','确认无人受伤令人安心而非 distressing。','word-choice'),[Q('distressing',1,1,'Distressing news is news that causes?','strong sadness or worry','complete amusement','no emotional response in anyone','distressing 指令人痛苦或忧虑的。'),Q('distressing',2,1,'Which situation is most likely distressing?','a family learns that their home was destroyed in a fire','a family receives a long-awaited safe arrival message','a child finds a favorite book','失去家园是令人痛苦的消息。'),Q('distressing',3,1,'Choose the natural construction: “It was distressing ___ the children suffer.”','to watch','watching to','for watched','常用 It is distressing to do sth。','grammar'),Q('distressing',4,1,'A distressing image would most likely make viewers feel?','upset or deeply concerned','proud of a routine success','hungry for lunch only','令人不安的画面会使人难过或担心。')]);
P('distribution','distribution 源自拉丁语 distributio，与 distribuere“分配、分派”有关；可指物资分发，也可指某种事物在空间或群体中的分布。',C('distribution.s2','生态调查','The map shows the distribution of the frog across wetlands, with most sightings clustered near clean streams.','地图展示了这种青蛙在湿地中的分布，大多数目击记录集中在洁净溪流附近。','The map shows the distribution of the frog across wetlands / with most sightings clustered / near clean streams.','distribution of + 物种/数值表示分布，对应 s2。','地图展示空间位置及聚集区域，符合分布义。'),M('The distribution of the donated coats left every box unopened in the warehouse.','The storage of the donated coats left every box unopened in the warehouse.','物资全部留在仓库未发放，属于储存而非分配。','word-choice'),[Q('distribution',1,1,'The distribution of food aid concerns?','how the supplies are delivered among recipients','how the food is cooked at home','the color of each package only','物资分配关注供应品如何送到受助者手中。'),Q('distribution',2,2,'A map of rainfall distribution shows?','where different amounts of rain occur','which farmers paid for the map','how water tastes','空间分布图展示降雨量在哪些地点出现。'),Q('distribution',3,1,'Which sentence uses the allocation sense?','The distribution of blankets began at the town hall.','The distribution of stars across the sky was photographed.','The map records the distribution of minerals in the rock.','毯子发放对应物资分配义。'),Q('distribution',4,2,'Which statement concerns geographic distribution?','The species occurs mainly along the northern coast.','Volunteers handed each family one food parcel.','The shop sent its products to customers.','沿北部海岸出现描述物种空间分布。')]);
P('distributor','distributor 由 distribute 加施动者后缀 -or 构成；distribute 来自拉丁语 distribuere“分派、分配”，可指负责供应或分发商品的公司/个人。',C('distributor.s1','供应链','The regional distributor delivered replacement filters to each clinic and tracked which sites had received them.','地区经销商向每家诊所交付替换滤芯，并跟踪各点的收货情况。','The regional distributor delivered replacement filters / to each clinic / and tracked which sites had received them.','distributor 为可数名词，常与 regional、authorized 等词搭配。','该机构将产品供应给多个诊所，符合经销/分销者义。'),M('The manufacturer selected a distributor to keep all products in one warehouse and never send them to retailers.','The manufacturer selected a storage contractor to keep products in a warehouse without distributing them.','只负责存放而不分销商品的公司不是 distributor。','word-choice'),[Q('distributor',1,1,'A regional distributor typically?','supplies goods to shops or customers in an area','designs the laws for a region','uses products without selling them','distributor 负责分销或供应产品。'),Q('distributor',2,1,'A book distributor helps a publisher by?','getting books to retailers and libraries','writing every chapter for the author','reviewing the author’s passport','经销商把书送到零售商或图书馆。'),Q('distributor',3,1,'Which phrase refers to an officially approved seller?','authorized distributor','authorized distribution','distribution authorizationly','authorized distributor 是授权经销商。','collocation'),Q('distributor',4,1,'A parts distributor and a parts manufacturer differ because the distributor mainly?','moves supplied parts through the sales network','creates every part from raw materials','repairs all machines personally','分销商主要负责供应链流通，不一定生产零件。')]);
P('disturbing','disturbing 由 disturb 加 -ing 构成；disturb 经古法语源自拉丁语 disturbare“扰乱”，常形容引起忧虑或不安的消息、迹象和行为。',C('disturbing.s1','公共安全','Investigators found a disturbing pattern of missing safety checks across several buildings owned by the same company.','调查人员发现，同一家公司拥有的多栋建筑都漏做安全检查，这一模式令人不安。','Investigators found a disturbing pattern / of missing safety checks / across several buildings owned by the same company.','disturbing 修饰 pattern，表示引起担忧而非单纯打扰。','反复遗漏安全检查预示潜在危险，令人忧虑。'),M('The disturbing report reassured residents because it found no hazard and confirmed every inspection was complete.','The reassuring report reassured residents because it found no hazard and confirmed every inspection was complete.','确认无危险并完成检查让人安心，不是 disturbing。','word-choice'),[Q('disturbing',1,1,'A disturbing discovery is one that?','causes concern or unease','is ordinary and comforting','cannot be noticed by anyone','disturbing 指令人不安的。'),Q('disturbing',2,1,'Which discovery would be disturbing to hospital staff?','several emergency alarms failed during a test','every alarm passed its test','a new bench was installed in the garden','急救警报测试失灵会引发不安。'),Q('disturbing',3,1,'A disturbing trend in injury reports should prompt people to?','investigate its causes and possible risks','ignore it because the word means entertaining','celebrate before checking the data','令人担忧的趋势需要调查原因和风险。'),Q('disturbing',4,1,'Disturbing evidence most nearly makes observers feel?','uneasy','sleepy from exercise','certain that nothing matters','disturbing evidence 令人不安。')]);
P('disunite','disunite 由 dis-“分开”加 unite“联合”构成；unite 源自拉丁语 unus“一个”，动词 disunite 可使群体分裂或彼此不和。',C('disunite.s1','社区治理','The rumor was intended to disunite the neighborhood by turning long-time residents against new families.','这则谣言意在挑拨社区，让老住户反对新搬来的家庭。','The rumor was intended to disunite the neighborhood / by turning long-time residents / against new families.','disunite + 群体作宾语表示使之分裂；by 引出手段。','谣言令社区成员分立对立，符合使分离义。'),M('The campaign disunited the volunteers by bringing them together around one shared goal.','The campaign united the volunteers by bringing them together around one shared goal.','共同目标使志愿者团结，而不是分裂。','word-choice'),[Q('disunite',1,1,'To disunite a team is to?','break its unity into opposing groups','help its members cooperate','choose a captain for it','disunite 表示使团体分裂。'),Q('disunite',2,1,'Which action could disunite a community?','spreading a rumor that encourages residents to distrust one another','organizing a joint cleanup day','creating a shared emergency plan','散播挑起互疑的谣言可能使社区分裂。'),Q('disunite',3,2,'In “The dispute disunited the family,” the family became?','divided by conflict','closer through cooperation','larger through adoption','这里是使家庭成员产生分裂、不和。'),Q('disunite',4,1,'Which verb contrasts with disunite?','unify','divide','alienate','unify 表示团结，与分裂相反。')]);
P('disuse','disuse 由 dis- 与 use 构成，表示因不再使用而废弃；名词常见于 in disuse，动词可指停止使用某物。',C('disuse.s2','设施管理','The council disused the old depot after a safer station opened on the other side of town.','城镇另一侧启用更安全的车站后，市议会停用了旧车场。','The council disused the old depot / after a safer station opened / on the other side of town.','disuse 可作及物动词，宾语为停止使用的设施；用作名词常说 in disuse。','车场不再投入使用，符合 s2 的停止使用义。'),M('The terminal fell into disuse because every passenger used it daily and all routes depended on it.','The terminal remained in use because every passenger used it daily and all routes depended on it.','每日使用且依赖的车站没有废弃。','word-choice'),[Q('disuse',1,1,'A building in disuse is?','no longer used for its intended purpose','newly opened to the public','being used more than ever','in disuse 表示废弃不用。'),Q('disuse',2,2,'If a council disuses an old bridge, it?','stops using the bridge','repairs it and reopens it immediately','changes the bridge into a road sign','动词 disuse 指停止使用某物。'),Q('disuse',3,1,'Choose the natural phrase: “The custom has fallen ___ disuse.”','into','over','beside','常见说法 fall into disuse。','collocation'),Q('disuse',4,1,'Which is evidence that a tool has fallen into disuse?','it has sat unused for years while a replacement does its job','workers rely on it every day','it was bought yesterday for daily use','多年无人使用体现废弃。')]);
P('diva','diva 源自意大利语 diva“女神”，本是歌剧中的杰出女歌手，尤其女主角；口语中也可指举止苛刻、爱摆架子的人。',C('diva.s2','工作场合','The crew called the actor a diva after she demanded a separate dressing room and refused to begin until the carpet was replaced.','演员要求单独化妆间，并拒绝在更换地毯前开工，剧组因此说她耍大牌。','The crew called the actor a diva / after she demanded a separate dressing room / and refused to begin until the carpet was replaced.','口语义 diva 带批评色彩；句中突出苛刻要求。','提出无理特殊要求且拒绝开工，体现耍大牌义。'),M('The crew called her a diva because she accepted the shared room and calmly helped everyone prepare.','The crew called her cooperative because she accepted the shared room and calmly helped everyone prepare.','体谅团队、接受共享空间不能证明她爱摆架子。'),[Q('diva',1,1,'In opera, a diva is traditionally?','a celebrated female singer, often a leading performer','the person who tunes the theater clock','a stage curtain','歌剧中的 diva 是著名女歌手，常任主角。'),Q('diva',2,2,'Calling someone a diva informally can criticize them for being?','demanding and self-important','quietly generous','unusually punctual only','口语 diva 可贬指苛刻、爱摆架子。'),Q('diva',3,2,'Which behavior best fits the informal sense of diva?','insisting that staff replace a perfectly clean carpet before work','helping the crew carry costumes','accepting a reasonable schedule','无必要地提出特殊要求体现耍大牌。'),Q('diva',4,1,'Which use refers to the traditional performance role rather than a personality criticism?','The diva received a standing ovation for her aria.','The diva refused to share the dressing room again.','The director joked that the diva demanded five assistants.','咏叹调获掌声指歌剧女主唱。')]);
P('diver','diver 由 dive 加施动者后缀 -er 构成；dive 可能经古英语与古诺斯语词形发展而来；diver 可指潜水员，也可指跳水运动员。',C('diver.s2','竞技体育','The diver held a straight line through the somersault and entered the pool with barely a splash.','这名跳水运动员翻腾时保持身体笔直，入水时几乎没有水花。','The diver held a straight line through the somersault / and entered the pool / with barely a splash.','diver 此处指竞技跳水者；enter the pool 描述入水动作。','空中翻腾、入池动作是跳水比赛表现，符合 s2。'),M('The diver explored the deep reef by performing a springboard routine judged for points.','The springboard athlete performed a routine judged for points; a scuba diver would explore the reef.','按跳台动作打分的是跳水运动员，不是水肺潜水探索者。','word-choice'),[Q('diver',1,1,'A scuba diver usually works or explores?','underwater using diving equipment','on a high board above a pool','inside an airplane cockpit','潜水员借助装备在水下活动。'),Q('diver',2,2,'A competitive diver is judged on?','a controlled jump and entry into the water','how many fish are on the reef','the depth of a cave','竞技跳水者按动作和入水表现评分。'),Q('diver',3,2,'Which scene describes the sports sense of diver?','She performed a twisting somersault from the platform.','He repaired a sunken boat using an air tank.','They mapped a coral reef underwater.','平台翻腾是跳水项目。'),Q('diver',4,1,'Which diver is most likely wearing a tank underwater?','a scuba diver','a springboard diver waiting at poolside','a diving judge','水肺潜水员需要水下呼吸装备。')]);
P('divergence','divergence 源自拉丁语 divergere“朝不同方向倾斜、分开”，加名词后缀 -ence；表示意见、路线或发展趋势之间的分歧/偏离。',C('divergence.s1','统计比较','There was a marked divergence between the two forecasts: one predicted a dry summer, while the other expected record rainfall.','两份预测明显不一致：一份预计夏季干旱，另一份却预测降雨量创纪录。','There was a marked divergence between the two forecasts / one predicted a dry summer / while the other expected record rainfall.','divergence between A and B 表示两者分歧。','两种预测方向相反，体现明显偏离。'),M('The forecasts showed a divergence because both made exactly the same prediction for every month.','The forecasts showed agreement because both made exactly the same prediction for every month.','完全相同的预测体现一致，而非 divergence。','word-choice'),[Q('divergence',1,1,'A divergence of opinion is?','a difference between people’s views','a complete agreement','a shared list of facts','divergence 指分歧、不同方向。'),Q('divergence',2,1,'Two economic forecasts show divergence when?','their projections move in different directions','their numbers and assumptions are identical','both omit the date','预测朝不同方向发展即分歧。'),Q('divergence',3,1,'Choose the usual construction: “a divergence ___ the accounts.”','between','amongst of','from with','常用 divergence between 表示两者间差异。','collocation'),Q('divergence',4,1,'Which pair most clearly shows divergence?','one route turns east while the other turns west','two routes follow the same road','two maps use the same scale','相反方向的路线体现 divergence。')]);
P('divergent','divergent 是 diverge 的 -ent 形容词形式；diverge 源自拉丁语 divergere“分道而行”，可指意见不同，也可指数学或光学中的发散。',C('divergent.s2','数学与光学','Parallel light rays become divergent after passing through the lens, spreading farther apart as they travel.','平行光线通过透镜后变为发散，传播时彼此距离越来越远。','Parallel light rays become divergent after passing through the lens / spreading farther apart / as they travel.','divergent 描写射线向外分开，对应 s2 的发散义。','光线之间间距增大，体现技术义 divergent。'),M('The lens produced divergent rays that moved steadily closer together until they met.','The lens produced convergent rays that moved steadily closer together until they met.','逐渐靠近并汇聚的是 convergent rays，不是 divergent。','word-choice'),[Q('divergent',1,1,'Divergent opinions are opinions that?','differ from one another','match in every respect','belong to the same person only','divergent 可指彼此不同的观点。'),Q('divergent',2,2,'Divergent rays travel?','farther apart from one another','closer together toward one point','in a circle around one source','发散光线彼此越走越远。'),Q('divergent',3,1,'Two researchers follow divergent methods when their methods?','develop in different directions','are exactly the same','use no evidence at all','研究方法走向不同即 divergent。'),Q('divergent',4,2,'Which word contrasts with divergent rays?','convergent','spreading','separating','convergent 表示汇聚，与发散相反。')]);
P('diversification','diversification 由 diversify 加名词后缀 -cation 构成；diverse 源于拉丁语 diversus“转向不同处”，该词表示增加种类或减少对单一来源的依赖。',C('diversification.s1','企业经营','The farm began diversification by growing berries and herbs, reducing its reliance on a single crop.','农场开始多样化经营，种植浆果和香草，以减少对单一作物的依赖。','The farm began diversification / by growing berries and herbs / reducing its reliance on a single crop.','diversification 可接 into/of，表示增加产品或投资种类。','增加作物种类并分散单一作物风险，符合多样化义。'),M('The company achieved diversification by selling only one product to one customer for its entire business.','The company increased its concentration by selling only one product to one customer for its entire business.','只依赖单一产品和客户体现集中而非多样化。','word-choice'),[Q('diversification',1,1,'Business diversification means?','adding different products or activities to reduce reliance on one','closing every product line except one','using the same supplier for every risk','diversification 指增加经营多样性并分散依赖。'),Q('diversification',2,1,'A farmer adds vegetables and beekeeping to a grain farm. This is?','diversification','specialization in grain alone','the removal of all crops','增加经营种类是多样化。'),Q('diversification',3,1,'Which change reduces investment risk through diversification?','spreading funds across several asset types','putting all savings into one company','borrowing more to buy the same share','将资金分散到多类资产有助降低集中风险。'),Q('diversification',4,1,'A diversification plan usually aims to?','create a broader mix of sources or activities','make every activity identical','increase dependence on a single item','多样化旨在拓宽来源或活动组合。')]);
P('diversified','diversified 是 diversify 的过去分词形容词；diversify 与拉丁语 diversus“转向不同处”相关，表示种类多样或业务/投资已经分散。',C('diversified.s1','投资组合','Her diversified portfolio included government bonds, local businesses, and international funds rather than one company alone.','她的多元化投资组合包括政府债券、本地企业和国际基金，而非只投一家公司。','Her diversified portfolio included government bonds, local businesses, and international funds / rather than one company alone.','diversified 修饰 portfolio，表示投资类别已经分散。','资金分布于不同资产，符合多样化的义项。'),M('The diversified portfolio held every dollar in a single speculative stock.','The concentrated portfolio held every dollar in a single speculative stock.','所有资金投向单一股票属于集中投资，不是 diversified。','word-choice'),[Q('diversified',1,1,'A diversified portfolio contains?','a mix of different investments','only one asset and no alternatives','a list of unpaid bills','多样化投资组合包含不同资产。'),Q('diversified',2,1,'A diversified company may earn income from?','several distinct business lines','one product alone by definition','no commercial activity','多元化公司可能经营多个业务领域。'),Q('diversified',3,1,'Which sentence uses diversified correctly?','The diversified farm sells fruit, dairy, and grain.','The diversified farm grows only one crop and has no other activity.','The diversified was farmed across yesterday.','多种农产品说明农场经营多元。'),Q('diversified',4,1,'Why might a diversified supplier base help a factory?','it reduces dependence on one source','it guarantees all suppliers are identical','it prevents the factory from buying materials','多供应来源可减少对单一供应者的依赖。')]);
P('diversify','diversify 由 diverse 加动词后缀 -ify 构成；diverse 源自拉丁语 diversus“朝不同方向”，动词可指扩大种类，也可泛指使变化。',C('diversify.s2','设计与生活','The architect used several materials and roof shapes to diversify the look of the housing block without changing its layout.','建筑师采用多种材料和屋顶形状，让住宅区外观有所变化，同时不改变布局。','The architect used several materials and roof shapes / to diversify the look of the housing block / without changing its layout.','diversify the look 表示使外观更丰富，对应 s2 的使变化义。','不同材料和造型令视觉呈现变化，符合 s2。'),M('The architect diversified the design by making every building identical in material, roof, and color.','The architect standardized the design by making every building identical in material, roof, and color.','所有元素完全相同是标准化，不是使之多样化。','word-choice'),[Q('diversify',1,1,'To diversify a product range is to?','add different kinds of products','remove every product except one','copy one product repeatedly','diversify 指增加种类、使多样化。'),Q('diversify',2,2,'To diversify a plain streetscape can mean to?','introduce variety into its appearance','make every building look identical','remove all visible differences','这里是使外观发生变化、增加多样性。'),Q('diversify',3,1,'A company dependent on one market may diversify by?','entering additional markets','selling only to the same customer','ending every line of business','进入额外市场可分散单一市场依赖。'),Q('diversify',4,1,'Which pattern is grammatical?','diversify its investments across sectors','diversify from its investments to sectors across','diversify to investing its across sectors','可说 diversify investments across sectors。','grammar')]);
P('diversion','diversion 来自 divert 加名词后缀 -ion；divert 源自拉丁语 divertere“转向一边”，可指转移注意，也可指娱乐消遣。',C('diversion.s2','休闲安排','The village museum is a pleasant diversion for hikers who need a quiet activity on a rainy afternoon.','对需要在雨天午后找项安静活动的徒步者来说，村庄博物馆是不错的消遣。','The village museum is a pleasant diversion for hikers / who need a quiet activity / on a rainy afternoon.','a diversion 可数，表示消遣活动，对应 s2。','参观博物馆提供休闲活动，符合娱乐消遣义。'),M('The museum served as a diversion from work because it added another urgent task to the visitor schedule.','The museum served as an extra duty rather than a diversion from work.','增添紧急工作不是消遣，语境与 diversion 的休闲义矛盾。','word-choice'),[Q('diversion',1,1,'A diversion from a difficult task is something that?','draws attention away from it','makes the task mandatory','measures how long it takes','diversion 可指把注意力转移开。'),Q('diversion',2,2,'A pleasant diversion on a holiday is?','an enjoyable activity for passing time','a serious emergency order','the official end of the holiday','diversion 的 s2 指娱乐或消遣。'),Q('diversion',3,2,'Which activity is a diversion for a bored child?','a puzzle game during a long wait','another hour of waiting with nothing to do','a warning that the event is canceled','游戏能作为消遣活动。'),Q('diversion',4,1,'A road diversion sends traffic?','along an alternative route','into the same closed lane','back to its starting point automatically','道路改道使交通转向替代路线。')]);
P('diversity','diversity 来自拉丁语 diversitas“差异、多样”，与 diversus“转向不同处”相关；既可指群体中多样性，也可指区别本身。',C('diversity.s2','比较与分类','The diversity between the two regional dialects is clear in their vowel sounds, although both speakers understand one another.','两个地区方言之间的差异在元音上十分明显，尽管双方说话者都能互相理解。','The diversity between the two regional dialects / is clear in their vowel sounds / although both speakers understand one another.','diversity between 两项表示彼此差异，对应 s2。','比较两种方言的元音差异，体现区别义。'),M('The diversity of the applicant pool increased after the committee accepted people from only one background.','The uniformity of the applicant pool increased after the committee accepted people from only one background.','只接纳一种背景会降低多样性并增加同质性。','word-choice'),[Q('diversity',1,1,'Diversity in a workplace refers to?','the presence of people with varied backgrounds or characteristics','everyone having exactly the same experience','the number of desks in the building','职场 diversity 指人员背景或特征多样。'),Q('diversity',2,2,'The diversity between two musical styles means?','the ways in which they differ','the fact that they are identical','the musicians share a rehearsal room','between 两种风格表示其差异。'),Q('diversity',3,1,'A school encourages diversity by?','welcoming students with different languages and experiences','requiring every student to share one background','removing all elective subjects','接纳不同语言和经历促进多样性。'),Q('diversity',4,1,'Which phrase is natural?','a diversity of opinions','a diversity between opinions is many','diversity to opinions of','a diversity of 表示多种意见。','collocation')]);
P('divisional','divisional 由 division 加形容词后缀 -al 构成；division 源自拉丁语 divisio“分开、划分”，divisional 可指组织部门的，也可指军事师级的。',C('divisional.s1','公司组织','The divisional office approved the regional budget, while the central finance team reviewed the company-wide accounts.','分部办公室批准了地区预算，而中央财务团队审核整个公司的账目。','The divisional office approved the regional budget / while the central finance team reviewed / the company-wide accounts.','divisional 修饰 office，表示分部或部门相关。','办公室负责某个业务分部而非总部，符合 s1。'),M('The divisional headquarters managed every branch as a single undivided unit with no separate departments.','The central headquarters managed every branch as a single undivided unit with no separate departments.','没有独立分部时不宜称 divisional headquarters。','word-choice'),[Q('divisional',1,1,'A divisional manager is responsible for?','one division or branch of a larger organization','every organization in the country','a private household only','divisional 表示某个部门/分部的。'),Q('divisional',2,1,'A divisional office differs from a central office because it?','serves a particular organizational unit','must govern the whole company','is always a military vehicle','部门办公室服务于特定组织单元。'),Q('divisional',3,1,'A divisional structure groups employees by?','separate product lines or business units','alphabetical order of their first names','the size of their shoes','分部式结构按业务或产品单位划分。'),Q('divisional',4,1,'Which phrase is grammatically natural?','divisional responsibilities','divisionally responsibility','divisionalize responsibility of','形容词 divisional 可修饰 responsibilities。','grammar')]);
P('dizziness','dizziness 由 dizzy 加名词后缀 -ness 构成；dizzy 可能源自古英语 dysig“愚钝、昏沉”，名词指头晕或使人眼花的感觉。',C('dizziness.s1','健康观察','The sudden dizziness made him sit down until the spinning sensation passed and he could walk steadily again.','突如其来的眩晕让他坐下休息，直到天旋地转的感觉消退、能够平稳行走。','The sudden dizziness made him sit down / until the spinning sensation passed / and he could walk steadily again.','dizziness 是不可数名词；a bout of dizziness 指一阵眩晕。','旋转感和站立不稳体现头晕义。'),M('Her dizziness improved as she kept climbing the ladder despite feeling the room spin.','Her dizziness worsened as she kept climbing the ladder despite feeling the room spin.','持续攀爬且房间旋转通常会加重而非改善眩晕。','context'),[Q('dizziness',1,1,'Dizziness is a sensation of?','lightheadedness or loss of balance','sharp hearing','increased appetite','dizziness 指头晕、眩晕感。'),Q('dizziness',2,2,'Bright rotating lights may cause dizziness that feels like?','visual confusion or a spinning sensation','a sore throat','a broken bone','眩目的灯光可使人眼花或感到旋转。'),Q('dizziness',3,1,'Which phrase is natural?','a bout of dizziness','a dizzinesses of spinning','dizzinessly feeling','a bout of dizziness 表示一阵眩晕。','collocation'),Q('dizziness',4,2,'After stepping off a fast carousel, she experienced?','dizziness from the moving scene','a fever caused by cold weather','a hearing loss from silence','快速旋转后视觉仍在晃动会令人头昏眼花。')]);
P('dizzying','dizzying 由 dizzy 加 -ing 构成，指使人眩晕、眼花，或速度/数量大到令人应接不暇；dizzy 可能承自古英语 dysig。',C('dizzying.s1','高速变化','The startup expanded at a dizzying pace, opening offices in twelve countries before its second anniversary.','这家初创公司以惊人的速度扩张，在成立两周年前便于十二个国家设立办公室。','The startup expanded at a dizzying pace / opening offices in twelve countries / before its second anniversary.','at a dizzying pace 是常见搭配，形容发展快得令人应接不暇。','短时间内跨多国扩张，体现速度快得惊人。'),M('The company grew at a dizzying pace by adding one customer over twenty years.','The company grew at a very slow pace by adding one customer over twenty years.','二十年仅增加一名客户是极慢速度，不是 dizzying pace。','word-choice'),[Q('dizzying',1,1,'A dizzying pace of change is?','so rapid that it is hard to keep up','slow enough to be barely noticed','a pace that never changes','dizzying 可指快得令人应接不暇。'),Q('dizzying',2,1,'Which workload could be called dizzying?','a worker receives hundreds of new requests in a single morning','a worker completes one routine task all month','a worker has no assignments','极短时间内出现大量任务会令人眼花。'),Q('dizzying',3,1,'The phrase “a dizzying height” suggests a height that?','may make someone feel unsteady or overwhelmed','is below the floor level','is easy to reach on foot','dizzying 可形容高到令人眩晕。'),Q('dizzying',4,1,'Which is a natural collocation?','a dizzying array of options','a dizzying silence of options','dizzily arrayed optionless','a dizzying array 表示多得令人眼花的一系列。','collocation')]);
P('DNA','DNA 是 deoxyribonucleic acid（脱氧核糖核酸）的首字母缩略语，名称概括了其脱氧核糖骨架和核酸性质；字母名读作 /ˌdiː en ˈeɪ/。',C('DNA.s1','遗传学','The laboratory compared DNA from the two samples to determine whether they came from the same person.','实验室比对两份样本中的 DNA，以确定它们是否来自同一个人。','The laboratory compared DNA from the two samples / to determine / whether they came from the same person.','DNA 通常作不可数名词；可说 DNA from a sample。','比对遗传物质以确认样本来源，符合该科学名词义。'),M('The report said the DNA test measured a person’s blood pressure and heart rate.','The report said the DNA test analyzed genetic material from the sample.','DNA 检测分析遗传物质，不是测量血压或心率。','word-choice'),[Q('DNA',1,1,'DNA is the molecule that primarily carries?','genetic information in living organisms','sound through the air','oxygen through every blood vessel','DNA 储存和传递遗传信息。'),Q('DNA',2,1,'A DNA sample is often compared to?','identify or test a possible biological relationship','measure the weather forecast','determine the age of a printed page','DNA 比对可用于身份或亲缘检验。'),Q('DNA',3,1,'What does the abbreviation DNA stand for?','deoxyribonucleic acid','deoxygenated nitrogen atom','double nucleotide arrangement','DNA 的全称是 deoxyribonucleic acid。'),Q('DNA',4,1,'Which claim is scientifically relevant to DNA?','a person inherits DNA from biological parents','DNA is a kind of blood pressure cuff','DNA is a unit for measuring rainfall','DNA 与遗传相关，并非测量单位或器械。')]);
P('doctoral','doctoral 由 doctor 加形容词后缀 -al 构成；doctor 经法语来自拉丁语 doctor“教师、指导者”，现多指博士学位或博士研究相关。',C('doctoral.s1','高等教育','Her doctoral research examines how urban trees reduce heat in neighborhoods with little green space.','她的博士研究考察城市树木如何降低绿地稀少社区的热度。','Her doctoral research examines / how urban trees reduce heat / in neighborhoods with little green space.','doctoral 修饰 research，表示博士阶段或博士学位相关。','研究课题属于博士研究内容，符合 doctoral 的义项。'),M('The doctoral thesis was submitted by a first-year primary-school pupil as a weekly spelling exercise.','The doctoral thesis was submitted by a graduate researcher for a doctorate.','博士论文是博士阶段的学术研究，不是小学生每周拼写练习。','context'),[Q('doctoral',1,1,'Doctoral research is work associated with?','a doctoral degree or PhD program','a driving license test','a primary-school spelling contest','doctoral 指博士学位或博士阶段相关。'),Q('doctoral',2,1,'A doctoral candidate is usually?','working toward a doctorate','already in kindergarten','a person who repairs clocks','doctoral candidate 是攻读博士学位的人。'),Q('doctoral',3,1,'Choose the natural phrase: “a ___ dissertation.”','doctoral','doctorate','doctorally','doctoral 作形容词修饰 dissertation。','grammar'),Q('doctoral',4,1,'Which subject might appear in a doctoral proposal?','a focused original research question','a list of grocery items only','a driver’s route home','博士研究计划应围绕具体原创研究问题。')]);
P('doctorate','doctorate 由 doctor 加表示学位/身份的后缀构成，经中世纪拉丁语 doctoratus 表示博士身份或博士学位；现代指最高层级研究学位之一。',C('doctorate.s1','学位申请','After completing her dissertation defense, Mina received a doctorate in environmental engineering.','完成论文答辩后，米娜获得了环境工程学博士学位。','After completing her dissertation defense / Mina received a doctorate / in environmental engineering.','receive/earn a doctorate in + 学科；doctorate 是可数名词。','答辩后授予学科博士学位，符合其义。'),M('He received a doctorate in biology after submitting only a high-school attendance form and no research work.','He received a high-school certificate after submitting an attendance form and no research work.','博士学位需要高阶学术研究，不能仅凭高中出勤表获得。','context'),[Q('doctorate',1,1,'A doctorate is?','an advanced academic degree earned through substantial study and research','a short school attendance note','a medical appointment time','doctorate 指博士学位。'),Q('doctorate',2,1,'A person may earn a doctorate in?','a named academic field such as physics','a single lunch break','the color of a diploma','doctorate 后可接研究学科。'),Q('doctorate',3,1,'Which verb commonly collocates with doctorate?','earn','borrow','taste','常见搭配 earn a doctorate。','collocation'),Q('doctorate',4,1,'After a successful dissertation defense, a candidate may be awarded?','a doctorate','a bus ticket','a weather report','论文答辩通过后可能获授博士学位。')]);
P('documentary','documentary 来自 document 加形容词/名词后缀 -ary；document 源于拉丁语 documentum“证明、教训”，documentary 可指纪实影片，也可表示文献或文件相关。',C('documentary.s2','档案研究','The historian found documentary evidence in shipping logs that confirmed when the families first arrived.','历史学家在航运日志中找到文献证据，证实了这些家庭最初到达的时间。','The historian found documentary evidence in shipping logs / that confirmed / when the families first arrived.','documentary 修饰 evidence，表示由文件记录构成，对应 s2。','航运日志是书面档案证据，符合文献/文件义。'),M('The historian called the evidence documentary although it consisted only of an unsourced rumor repeated orally.','The historian called the evidence hearsay because it consisted only of an unsourced oral rumor.','无出处口述传闻不是书面文献证据。','word-choice'),[Q('documentary',1,1,'A documentary is a film that?','presents factual events or subjects','is always a fictional romance','contains no images or sound','documentary 可指纪实影片。'),Q('documentary',2,2,'Documentary evidence is evidence based on?','records, documents, or written sources','a purely invented story','an unexplained dream','documentary 的形容词义是文件或记录相关。'),Q('documentary',3,1,'Which item is documentary evidence for an old shipment?','a dated cargo manifest','a rumor with no source','a modern fictional scene','货单是可核查的书面记录。'),Q('documentary',4,1,'A documentary about a river is most likely to?','present researched information about the river','invent a river kingdom with magical animals','teach only how to paint a frame','纪录片通常呈现真实主题和研究资料。')]);
P('documentation','documentation 由 document 加 -ation 构成；document 源自拉丁语 documentum“证明、教训”，documentation 可指证明文件，也可指书面记录或使用说明。',C('documentation.s2','软件维护','The software documentation explains how each command works and lists the expected format for its input.','软件文档说明每条命令如何工作，并列出输入所需格式。','The software documentation explains / how each command works / and lists the expected format for its input.','documentation 作不可数名词，表示操作说明/技术文档，对应 s2。','文档记录命令功能与输入格式，符合记录说明义。'),M('The software documentation consisted of executable code only and gave users no written instructions or reference information.','The software package included executable code but lacked user documentation.','没有书面说明或参考信息就没有 documentation。','word-choice'),[Q('documentation',1,1,'A passport and visa may serve as?','documentation proving identity or permission','a type of weather forecast','a musical instrument','documentation 可指证明文件。'),Q('documentation',2,2,'Software documentation helps a user by?','explaining commands and expected inputs','physically repairing a broken screen','changing the computer’s electricity supply','技术文档提供操作说明和参考信息。'),Q('documentation',3,1,'Which phrase is natural?','supporting documentation','documentationly support','a documentation ofs','supporting documentation 是常见搭配。','collocation'),Q('documentation',4,2,'An instruction manual is a form of?','documentation','a passport photograph','a software error itself','手册属于文档说明。')]);
P('doggedly','doggedly 由 dogged 加副词后缀 -ly 构成；dogged 表“持续不放弃的”，常被解释为像狗紧追不舍般执着，但该比喻来源不宜绝对断言。',C('doggedly.s1','长期训练','Despite repeated setbacks, the young pianist practiced doggedly each morning until she could perform the difficult passage cleanly.','尽管屡遭挫折，这位年轻钢琴家仍每天早晨顽强练习，直到能流畅演奏那段难曲。','Despite repeated setbacks / the young pianist practiced doggedly each morning / until she could perform the difficult passage cleanly.','doggedly 修饰 practiced，表示持续顽强地做某事。','面对挫折仍日复一日练习，体现坚韧不懈。'),M('The team pursued the goal doggedly by abandoning it after the first minor setback.','The team pursued the goal briefly by abandoning it after the first minor setback.','遇到小挫折立刻放弃不能称为 doggedly 坚持。','word-choice'),[Q('doggedly',1,1,'To work doggedly is to work?','with persistent determination','only when success is guaranteed','without any goal or effort','doggedly 表示顽强、坚持不懈地。'),Q('doggedly',2,1,'Which student studies doggedly?','one who continues reviewing despite several failed attempts','one who quits as soon as a problem appears','one who never opens the book','遇到困难仍持续复习体现坚持。'),Q('doggedly',3,1,'Doggedly is closest in meaning to?','persistently','carelessly','temporarily','persistently 表示坚持不懈地。'),Q('doggedly',4,1,'A reporter doggedly follows a lead by?','checking each new clue until the facts are clear','dropping the inquiry at the first unanswered question','publishing a guess without checking','持续核实线索体现执着追查。')]);
P('dogmatic','dogmatic 由 dogma 加形容词后缀 -atic 构成；dogma 源自希腊语 dogma“意见、教义”，经拉丁语进入英语；dogmatic 可指武断，也可指依据既定教条。',C('dogmatic.s2','宗教与思想史','The lecturer explained how the dogmatic rules of the order shaped its daily rituals and formal teachings.','讲师解释该教团的教条规则如何塑造日常仪式和正式教义。','The lecturer explained / how the dogmatic rules of the order / shaped its daily rituals and formal teachings.','dogmatic 修饰 rules，表示与一套既定教义相连，对应 s2。','固定教义规则支配仪式和教学，体现教条义。'),M('Her dogmatic position welcomed every challenge and changed whenever new evidence appeared.','Her flexible position welcomed every challenge and changed whenever new evidence appeared.','乐于修正的立场不是坚持教条或武断的 dogmatic。','word-choice'),[Q('dogmatic',1,1,'A dogmatic speaker tends to?','state opinions as unquestionable and resist alternatives','present every claim as tentative','change views whenever anyone speaks','dogmatic 常指武断地坚持观点。'),Q('dogmatic',2,2,'Dogmatic teaching in a religious order is based on?','fixed doctrines or authoritative principles','random guesses made each morning','a refusal to teach any belief','dogmatic 的 s2 指依据既定教义的。'),Q('dogmatic',3,1,'Which response sounds dogmatic?','“No evidence could ever change my conclusion.”','“Let us review the new evidence before deciding.”','“I am unsure and want to hear other views.”','拒绝任何证据改变结论体现武断。'),Q('dogmatic',4,1,'Dogmatic is often critical because it suggests?','excessive certainty and inflexibility','careful openness to revision','complete lack of any opinion','该词常批评过度确定、缺乏灵活性。','register')]);
P('dogwood','dogwood 是英语树名，16世纪已有记录；词中 wood 指木本植物部分，而 dog 的历史来源并无公认定论，因此不把不确定部分硬拆成确定词根。',C('dogwood.s1','植物观察','The dogwood outside the library blooms with small pale flowers each spring, and birds feed on its later berries.','图书馆外的山茱萸每年春天开出浅色小花，之后鸟类会取食它的果实。','The dogwood outside the library blooms with small pale flowers each spring / and birds feed on its later berries.','dogwood 是可数树木名，常见复数 dogwoods。','该句描述开花结果的山茱萸树，体现其植物义。'),M('The botanist identified the dogwood as a metal alloy mined from a mountain seam.','The botanist identified the dogwood as a flowering tree with berries.','dogwood 是植物名称，不是金属合金。','word-choice'),[Q('dogwood',1,1,'Dogwood is the name of?','a group of flowering trees or shrubs','a kind of steel cable','a type of ocean current','dogwood 指山茱萸属植物。'),Q('dogwood',2,1,'Which clue suggests a plant is a dogwood?','it is a tree with spring flowers and later berries','it is a metal object with threaded bolts','it is a cloud that forms over the sea','春花与果实是山茱萸植物特征。'),Q('dogwood',3,1,'A gardener would most likely plant dogwood in?','a garden or landscape','a machine engine','a glass of drinking water','dogwood 是可种植的树木/灌木。'),Q('dogwood',4,1,'Which sentence uses dogwood correctly?','The dogwood shaded the path with its branches.','She dogwooded the report before lunch.','The dogwood measured the temperature of the oven.','树木可为小路遮荫。')]);
P('doleful','doleful 由 dole（悲伤、哀痛）加 -ful 构成；dole 曾有“悲痛”义，词源细节有争议；doleful 可形容悲哀的表情/声音，也可形容阴沉的景象。',C('doleful.s2','天气描写','Under a low gray sky, the empty playground looked doleful, with wet swings hanging motionless above the puddles.','低沉的灰色天空下，空荡的游乐场显得阴郁，湿漉漉的秋千静静悬在水洼上方。','Under a low gray sky / the empty playground looked doleful / with wet swings hanging motionless above the puddles.','doleful 作表语形容环境气氛阴沉，对应 s2。','灰暗、空寂的景象带来阴郁感，体现 s2。'),M('The doleful landscape was bright, cheerful, and filled with children laughing in warm sunlight.','The cheerful landscape was bright and filled with children laughing in warm sunlight.','明亮欢快的景象与阴郁的 doleful 相反。','word-choice'),[Q('doleful',1,1,'A doleful expression suggests?','sadness or grief','amusement','anger about a minor delay only','doleful 描写悲哀、忧伤。'),Q('doleful',2,2,'A doleful landscape is likely?','gloomy and depressing','bright and festive','crowded with cheerful celebrations','该词也能描写阴沉、令人忧郁的环境。'),Q('doleful',3,1,'Which voice would sound doleful?','a low, sorrowful voice after bad news','a delighted laugh at a party','an excited cheer at a victory','悲伤消息后的低沉语气符合 doleful。'),Q('doleful',4,2,'Which scene best fits the atmospheric sense of doleful?','a deserted street beneath cold rain','a sunny park during a joyful festival','a lively beach picnic','阴冷雨中空街显得阴郁。')]);
P('dolmen','dolmen 源自布列塔尼语 dolmen，通常分析为 dol“桌子”与 men“石头”，即史前墓葬的石桌状结构。',C('dolmen.s1','考古遗址','Archaeologists mapped the dolmen before excavation, recording how its capstone rested on upright stones.','考古学家在挖掘前绘制了这座石棚的地图，记录顶石如何架在直立石柱上。','Archaeologists mapped the dolmen before excavation / recording how its capstone / rested on upright stones.','dolmen 是可数名词，指史前石棚墓；capstone 是顶石。','顶石由竖石支撑，正是石棚遗址结构。'),M('The guide described the dolmen as a modern glass skyscraper built last year in the city center.','The guide described the building as a modern glass skyscraper built last year in the city center.','dolmen 指史前巨石墓，不是现代摩天楼。','word-choice'),[Q('dolmen',1,1,'A dolmen is an ancient structure made mainly of?','large stones arranged like a chamber or table','thin sheets of plastic','woven reeds and cloth','dolmen 是史前巨石结构。'),Q('dolmen',2,1,'Which feature commonly identifies a dolmen?','a large capstone resting on upright stones','a steel roof held by elevators','a clay pot buried alone','顶石由直立巨石支撑是其典型结构。'),Q('dolmen',3,1,'A dolmen is most likely studied by?','archaeologists examining prehistoric sites','astronomers measuring distant stars','accountants reviewing annual budgets','dolmen 属于考古遗址对象。'),Q('dolmen',4,1,'Which description uses dolmen accurately?','The prehistoric dolmen stood in a field on stone supports.','The dolmen streamed music through a phone app.','The baker poured the dolmen into a cup.','史前石棚可立于田野中。')]);
P('dolorous','dolorous 源自拉丁语 dolorosus“充满痛苦的”，来自 dolor“疼痛、悲伤”；形容词表示悲痛、忧伤，语气较文学或正式。',C('dolorous.s1','文学叙述','A dolorous melody drifted from the chapel as villagers gathered to mourn the lost sailors.','村民聚集悼念遇难水手时，一段悲伤的旋律从小教堂中飘出。','A dolorous melody drifted from the chapel / as villagers gathered / to mourn the lost sailors.','dolorous 修饰 melody，常用于文学性的悲伤描写。','哀悼场景中的旋律忧伤，符合 dolorous。'),M('The dolorous tune celebrated the team victory with joyful dancing and triumphant cheers.','The jubilant tune celebrated the team victory with joyful dancing and triumphant cheers.','庆祝胜利的欢快旋律不应称为悲痛的 dolorous。','word-choice'),[Q('dolorous',1,1,'A dolorous song is?','sorrowful and mournful','lighthearted and comic','silent and without melody','dolorous 指悲痛、忧伤的。'),Q('dolorous',2,1,'A dolorous face after a funeral would look?','sad and grieving','triumphant and amused','bored by mathematics','葬礼后的悲容体现哀伤。'),Q('dolorous',3,1,'Dolorous is most common in which style?','formal or literary writing','informal text messages only','technical instructions for cooking','dolorous 较文学、正式。','register'),Q('dolorous',4,1,'Which phrase is natural?','a dolorous lament','a dolorous celebration of a comic triumph','a dolorous recipe for boiling water','哀歌 lament 可以是悲痛的。','collocation')]);
P('domelike','domelike 由 dome 加 -like 构成，表示形状像圆顶；dome 经法语来自意大利语/拉丁语 domus“房屋”，后用于半球形屋顶或结构。',C('domelike.s1','建筑观察','The station covered its ticket hall with a domelike roof that let sunlight reach the central waiting area.','车站为售票大厅建了穹顶状屋顶，让阳光照进中央候车区。','The station covered its ticket hall with a domelike roof / that let sunlight reach / the central waiting area.','-like 表示“像……的”；domelike 在 roof 前作定语。','屋顶呈圆顶形状，符合 domelike。'),M('The observatory had a domelike roof shaped as a perfectly flat square slab.','The observatory had a flat square roof shaped as a slab.','完全平坦的方形板没有穹顶形状。','word-choice'),[Q('domelike',1,1,'A domelike ceiling is shaped?','like a rounded dome','like a flat floor','like a narrow staircase','-like 表示类似；domelike 即圆顶状。'),Q('domelike',2,1,'Which object is domelike?','a rounded greenhouse roof arching over the room','a perfectly flat square board','a long straight wire','拱起的温室屋顶像圆顶。'),Q('domelike',3,1,'The suffix -like in domelike means?','having a form similar to','made entirely from','located underneath','-like 表示“像……的”。'),Q('domelike',4,1,'Which sentence uses domelike correctly?','A domelike canopy sheltered the fountain.','The domelike ran quickly through the garden.','She domeliked the letter yesterday.','domelike 是修饰 canopy 的形容词。')]);
P('domestically','domestically 由 domestic 加 -ally 构成；domestic 来自拉丁语 domesticus“家庭的、家中的”，副词可指在本国范围内，也可指在家庭生活方面。',C('domestically.s1','贸易新闻','The company sells most of its products domestically, although a small share is shipped to neighboring countries.','这家公司大部分产品在国内销售，不过也有少量运往邻国。','The company sells most of its products domestically / although a small share / is shipped to neighboring countries.','domestically 修饰 sells，表示在本国境内，对应 s1。','与少量出口相对，国内销售是句子重点。'),M('The retailer sells its goods domestically only in foreign countries and never within its home market.','The retailer sells its goods internationally only in foreign countries and never within its home market.','domestically 指在本国境内，不是只在外国。','word-choice'),[Q('domestically',1,1,'A product sold domestically is sold?','within its own country','only in another country','inside a private home necessarily','domestically 的 s1 指在本国范围内。'),Q('domestically',2,2,'Someone who works domestically may work?','in the home or household sphere','only in a foreign embassy','under the ocean','domestically 也可表示家庭生活方面。'),Q('domestically',3,1,'A firm produces domestically but exports some goods. Where are they produced?','in the firm’s home country','only abroad','in a household kitchen by definition','该搭配描述在本国生产。'),Q('domestically',4,1,'Which sentence uses the home-life sense?','She was responsible for managing domestically while her partner traveled.','The factory domestically ships cargo only overseas.','The ship sailed domestically beneath the sea.','家庭管理语境对应 domestically 的家庭义。')]);
P('domesticate','domesticate 由 domestic 加动词后缀 -ate 构成；domestic 来自拉丁语 domesticus“家中的”，动词可指驯养野生物种，也可指使某物适应家庭或本地环境。',C('domesticate.s2','食物与文化','The chef domesticated the unfamiliar recipe by replacing a rare spice with ingredients available in local markets.','厨师把陌生食谱本地化，用当地市场买得到的食材替换稀有香料。','The chef domesticated the unfamiliar recipe / by replacing a rare spice / with ingredients available in local markets.','domesticate 可比喻使事物适应当地或家庭环境，对应 s2。','改用本地食材使食谱适应本地环境，体现转化义。'),M('The biologist domesticated the wild fox by releasing it far from people and preventing any contact.','The biologist kept the wild fox feral by releasing it far from people and preventing any contact.','隔离人类并放归野外不能使狐狸驯化。','word-choice'),[Q('domesticate',1,1,'To domesticate an animal is to?','breed or train it to live with people','return it to a completely wild habitat','classify it as a mineral','domesticate 可指驯养动物。'),Q('domesticate',2,2,'To domesticate an unfamiliar custom can mean to?','adapt it to local or home use','make it more difficult to understand','remove it from every community','比喻义可指使事物适应本地/家庭环境。'),Q('domesticate',3,1,'Which example shows animal domestication?','people selectively breed wild ancestors over generations','a wolf avoids every human and remains wild','a fossil is displayed in a museum','长期选育使野生祖先成为家养动物。'),Q('domesticate',4,1,'A company domesticated an imported design by?','adapting it to local needs and materials','copying it unchanged despite incompatibility','discarding every version','适配本地需求体现 domesticate 的转化义。')]);
P('domestication','domestication 由 domesticate 加名词后缀 -ion 构成；domesticate 与 domesticus“家庭的”相关，此名词多指人类驯养动物或栽培植物的过程。',C('domestication.s1','农业史','The domestication of wheat allowed early communities to store grain and remain in one place for longer periods.','小麦的驯化使早期社群能够储存谷物并在同一地点居住更久。','The domestication of wheat allowed early communities / to store grain / and remain in one place for longer periods.','domestication of + 物种；此处指长期驯化/栽培过程。','种植并储粮反映人类对野生植物的驯化。'),M('The domestication of wild horses meant that people avoided breeding or training them and left them entirely unmanaged.','The preservation of wild horses meant that people avoided breeding or training them and left them unmanaged.','不繁育、不训练野马不构成驯化。','word-choice'),[Q('domestication',1,1,'The domestication of a species is the process of?','bringing it under human breeding or care over generations','turning it into a fossil','removing it from all human contact','domestication 指驯化过程。'),Q('domestication',2,1,'Which development is evidence of plant domestication?','farmers select seeds from plants with useful traits','wild seeds are never planted or selected','a rock is shaped into a tool','选择有用性状的种子进行栽培是驯化。'),Q('domestication',3,1,'Animal domestication usually involves?','selective breeding and adaptation to living with people','a single animal being seen once in a forest','changing an animal into a different species overnight','驯化通常是长期选育和适应人类环境。'),Q('domestication',4,1,'Which field studies the domestication of crops?','archaeobotany and agricultural history','astrology','marine navigation','作物驯化属于植物考古和农业史研究。')]);
P('domicile','domicile 源自拉丁语 domicilium“住所”，由 domus“家”与 colere“居住”构成；名词可指住所或法律上的固定居所，也可作动词使人定居。',C('domicile.s1','法律身份','For tax purposes, the court treated the country where she permanently intended to live as her domicile.','在税务问题上，法院将她打算永久居住的国家认定为住所地。','For tax purposes / the court treated the country where she permanently intended to live / as her domicile.','domicile 作法律名词，常指永久居所/住所地；be domiciled in 是相关结构。','法院根据永久居住意图认定法律住所，符合 s1。'),M('The court called a temporary hotel room her permanent domicile even though she had lived there for one night.','The court called her long-term home her domicile because she had lived there for years.','只住一晚的临时旅馆通常不构成永久法律住所。','context'),[Q('domicile',1,1,'A person’s domicile is generally their?','permanent or legally recognized home','temporary seat on a bus','place where a passport was printed','domicile 指固定住所或法律住所地。'),Q('domicile',2,1,'A court determining domicile may consider?','where the person intends to live permanently','which hotel served breakfast best','the color of the person’s suitcase','永久居住意图是判断 domicile 的相关因素。'),Q('domicile',3,1,'Which phrase is natural in legal writing?','her domicile was in the northern state','her domicile was under yesterday','she domicile her suitcase','domicile 可作名词表示法律住所。','grammar'),Q('domicile',4,1,'A weekend hotel stay is usually not a person’s domicile because it is?','temporary rather than a settled home','their intended permanent residence','the place where they hold legal residence','短暂停留通常不等于固定住所。')]);
P('dominant','dominant 源自拉丁语 dominantem，是 dominari“统治、支配”的现在分词；可指占主导地位，也可在遗传学中指显性基因。',C('dominant.s2','遗传学','In this simplified inheritance example, the dominant allele determines the visible trait when paired with a recessive allele.','在这个简化的遗传示例中，显性等位基因与隐性等位基因配对时决定可见性状。','In this simplified inheritance example / the dominant allele determines the visible trait / when paired with a recessive allele.','dominant allele 是遗传学搭配，对应 s2；显性并不表示更常见或更优越。','一个等位基因在杂合配对时表达该性状，体现显性义。'),M('The dominant allele appears only when paired with a second recessive copy and never affects the trait by itself.','The recessive allele is masked when paired with a dominant copy in this simplified example.','dominant 在该遗传模型中不是只有与隐性配对才隐藏表达。','word-choice'),[Q('dominant',1,1,'A dominant company in a market is one that?','has a leading or controlling position','has no customers at all','is the newest company by definition','dominant 的常见义是占主导。'),Q('dominant',2,2,'In a basic genetics lesson, a dominant allele is one that?','can determine the expressed trait when paired with a recessive allele','is always less visible than a recessive allele','must be harmful','遗传学 dominant 指可在相应配对中表达的显性等位基因。'),Q('dominant',3,1,'A dominant theme in a novel is?','the main or most influential theme','a detail mentioned once and never developed','the title of the last chapter only','dominant theme 是主要主题。'),Q('dominant',4,2,'Which statement uses the genetic sense?','The dominant form of the trait appeared in the first-generation plants.','One firm held a dominant share of the market.','A dominant color filled most of the painting.','遗传性状表达对应 s2。')]);
P('domination','domination 来自 dominate 加名词后缀 -ion；dominate 源自拉丁语 dominari“作主人、统治”，名词指对他人或领域的控制、支配。',C('domination.s1','团队协作','The report warned that one manager’s domination of every discussion discouraged junior staff from sharing concerns.','报告警告，一名经理垄断每场讨论的主导权，使初级员工不愿提出担忧。','The report warned / that one manager’s domination of every discussion / discouraged junior staff from sharing concerns.','domination of + 群体/活动表示控制或支配；discourage sb from doing。','经理控制所有讨论并压制他人发言，符合支配义。'),M('The domination of the meeting ended when the chair invited every member to contribute equally and listened to each view.','The chair ended one person’s domination of the meeting by inviting every member to contribute equally.','均等发言和倾听结束了个人支配，而不是 domination 本身。','word-choice'),[Q('domination',1,1,'Domination of a team means?','exercising controlling power over its members','sharing all decisions equally','leaving the team without a leader','domination 指控制、支配。'),Q('domination',2,1,'Which situation shows one person’s domination of a meeting?','one speaker prevents others from contributing','the chair invites balanced discussion','members vote on several options','阻止他人发言、垄断讨论体现支配。'),Q('domination',3,1,'Domination in sports can mean?','one team consistently controls the competition','all teams share exactly the same results','a game has no players','一队持续控制比赛体现统治地位。'),Q('domination',4,1,'Which action would reduce domination in a group?','rotate leadership and give members equal speaking time','allow one member to veto every contribution','exclude all other members','轮换领导并平等发言可减少单方支配。')]);
P('domineering','domineering 由 domineer 加 -ing 构成；domineer 与 dominus“主人、统治者”相关，形容以命令口吻控制他人、专横跋扈的。',C('domineering.s1','团队管理','The domineering supervisor assigned every task herself and dismissed suggestions before anyone could finish speaking.','这位专横的主管独自分派所有任务，别人话还没说完就否决建议。','The domineering supervisor assigned every task herself / and dismissed suggestions / before anyone could finish speaking.','domineering 修饰 supervisor，表现控制欲强、不给他人空间。','垄断决定并打断他人，体现专横盛气凌人的 s1。'),M('The domineering chair invited quiet members to speak first and accepted the group decision without imposing her own view.','The considerate chair invited quiet members to speak first and accepted the group decision without imposing her own view.','倾听他人、接受共同决定不属于专横。'),[Q('domineering',1,1,'A domineering person tends to?','control others and insist on having their own way','invite others to make decisions freely','avoid giving any instructions ever','domineering 表示专横控制他人。'),Q('domineering',2,2,'A domineering leader may be described as?','overbearing or high-handed','carefully impartial','unable to make a decision','s2 可形容跋扈、盛气凌人。'),Q('domineering',3,1,'Which manager behaves domineeringly?','one who rejects all input and dictates every detail','one who asks staff to share proposals','one who delegates and listens','拒绝所有意见并独断安排体现 domineering。'),Q('domineering',4,1,'The closest opposite of domineering is?','respectful and consultative','overbearing','controlling','尊重并协商与专横相反。')]);
P('donor','donor 由 donate 加施动者后缀 -or 构成；donate 源自拉丁语 donare“给予”，donor 可指捐赠人，也可指提供血液或器官的供体。',C('donor.s2','移植医学','The donor gave one kidney to her brother, and the transplant team carefully monitored both patients afterward.','供体把一侧肾脏捐给了弟弟，移植团队随后仔细监测两位患者。','The donor gave one kidney to her brother / and the transplant team / carefully monitored both patients afterward.','organ donor 表示器官供体；此处符合 s2。','捐出肾脏作为移植来源，体现供体义。'),M('The donor received a kidney from the patient and was listed as the person who supplied the organ.','The recipient received a kidney from the donor and was listed as the person who received the organ.','供体提供器官；接受移植的人是 recipient。','word-choice'),[Q('donor',1,1,'A donor to a museum is someone who?','gives money or an object to support it','borrows its exhibits','writes the museum rules only','donor 可指捐赠人。'),Q('donor',2,2,'An organ donor is a person who?','provides an organ for transplantation','receives an organ during surgery','manufactures an artificial heart','器官 donor 是供体。'),Q('donor',3,2,'In a blood donation, the donor is the person who?','gives the blood','receives the blood','tests the blood pressure','供血者是 donor。'),Q('donor',4,1,'A donor-funded library received its books from people who?','gave books or funds to support it','bought every book for resale','borrowed all the shelves','donor 可捐赠物品或资金。')]);
P('doodle','doodle 是英语口语词，记录为随手乱画或涂鸦的动词/名词；其更早词源并无可靠定论，因此不把相似拼写误当成已证实词根。',C('doodle.s2','课堂笔记','The margin of her notebook was filled with a doodle of a tiny house surrounded by flowers.','她的笔记本页边画着一幅小涂鸦：一座房子周围开满了花。','The margin of her notebook was filled with a doodle / of a tiny house / surrounded by flowers.','a doodle of + 图画内容；此处名词指随手画的小图。','页边的小房子画是非正式随手涂鸦，符合 s2。'),M('He drew a doodle the moon in the margin and labeled it with the date.','He drew a doodle of the moon in the margin and labeled it with the date.','表示图画内容时常用 doodle of + 名词。','collocation'),[Q('doodle',1,2,'A doodle in a notebook is usually?','a casual, simple drawing made absent-mindedly','a signed legal contract','a carefully printed photograph','doodle 作名词可指随手画的小图。'),Q('doodle',2,1,'To doodle during a phone call is to?','make informal sketches while talking','write a formal report','erase the phone number from memory','动词 doodle 是随手涂画。'),Q('doodle',3,2,'Which phrase is natural?','a doodle of a bird','a doodle at a bird of','a doodle birdly','常用 a doodle of + 图画内容。','collocation'),Q('doodle',4,1,'Which action is doodling?','sketching small shapes on scrap paper while waiting','painting a house wall with industrial paint','signing a tax return','等待时在纸上随手画图属于 doodling。')]);
P('doomed','doomed 是 doom 的过去分词形容词；doom 源自古英语 dom“判决、命运”，可指注定失败、遭受毁灭或无法挽回的结局。',C('doomed.s1','灾难预警','Without repairs to the cracked supports, the old bridge was doomed to collapse under the next heavy truck.','如果不修补开裂的支撑结构，这座旧桥注定会被下一辆重型卡车压塌。','Without repairs to the cracked supports / the old bridge was doomed to collapse / under the next heavy truck.','be doomed to + 名词/动词原形表示注定遭遇不幸结果。','结构破损且不修复，预示桥必然倒塌，符合 doomed。'),M('The doomed bridge was certain to remain safe because engineers had repaired every cracked support.','The bridge was no longer doomed to collapse because engineers had repaired every cracked support.','关键风险已修复时，不能再断言桥注定倒塌。','context'),[Q('doomed',1,1,'A plan doomed to fail is?','certain or very likely to fail','guaranteed to succeed','not yet imagined by anyone','doomed to fail 表示注定失败。'),Q('doomed',2,1,'Which project seems doomed?','one with no funding, no staff, and an impossible deadline','one with a clear budget and enough time','one that has already met its goals','缺资金、缺人手且期限不可能的项目极可能失败。'),Q('doomed',3,1,'Complete the common pattern: “They were doomed ___ lose.”','to','for','at','固定结构是 be doomed to do。','grammar'),Q('doomed',4,1,'The survivors realized the expedition was doomed when?','the only boat sank before the storm arrived','a second supply ship reached the island','the weather cleared and food arrived','唯一逃生船沉没使远征几乎注定失败。')]);
P('doomsday','doomsday 由 doom 加 day 构成，承自古英语 domes dæg“审判之日”；现代可指世界末日，也可比喻毁灭性灾难时刻。',C('doomsday.s2','风险评估','The engineers prepared for a doomsday scenario in which both the power grid and the backup generators failed.','工程师为电网和备用发电机同时失灵这种灾难性情形作了准备。','The engineers prepared for a doomsday scenario / in which both the power grid / and the backup generators failed.','doomsday scenario 是夸张表达，指极端灾难性情景，对应 s2。','关键系统同时崩溃构成灾变情景。'),M('The manual called a routine software update a doomsday scenario even though it involved no serious risk.','The manual called a routine software update a minor maintenance task because it involved no serious risk.','无严重风险的日常更新不应夸称为灾变时刻。','word-choice'),[Q('doomsday',1,1,'Doomsday traditionally refers to?','the end of the world or final judgment','the first day of a school term','a routine lunch break','doomsday 传统上指世界末日或末日审判。'),Q('doomsday',2,2,'A doomsday scenario is a?','catastrophic worst-case situation','minor inconvenience with no consequences','ordinary daily schedule','比喻义指极端灾难情景。'),Q('doomsday',3,1,'A newspaper uses doomsday language about a small delay. The tone is likely?','exaggerated and alarmist','carefully neutral','celebratory','将小延误说成末日灾难属于危言耸听。','register'),Q('doomsday',4,2,'Which event fits the modern figurative sense?','a cascading failure shuts down essential systems','a printer runs out of paper','a meeting starts five minutes late','关键系统连锁失灵是灾变情景。')]);
P('doorknob','doorknob 由 door 与 knob 组成，字面指安装在门上供手握、转动或拉动的球形门把手。',C('doorknob.s1','家居安全','She turned the loose doorknob slowly, then tightened its screws before the latch stopped catching.','她慢慢转动松动的球形门把手，然后拧紧螺丝，门闩这才不再卡住。','She turned the loose doorknob slowly / then tightened its screws / before the latch stopped catching.','turn a doorknob 表示转动门把手。','门把手松动、转动后影响门闩，对应物件义。'),M('He opened the door by turning the doorknob on the ceiling above the bed.','He opened the door by turning the doorknob beside the door.','doorknob 安装在门上，不会装在床上方天花板。','context'),[Q('doorknob',1,1,'A doorknob is attached to a?','door','windowpane','floor tile','doorknob 是门上的把手。'),Q('doorknob',2,1,'To open a door with a round doorknob, you usually?','turn or pull the knob','twist the floorboard','press the window glass','球形门把手通常通过转动或拉动操作。'),Q('doorknob',3,1,'Which sentence is natural?','She polished the brass doorknob.','She polished the brass doorknob of her lunch.','She doorknobly polished the brass.','brass doorknob 指黄铜门把手。','grammar'),Q('doorknob',4,1,'A loose doorknob may need?','its screws tightened','a passport renewed','a tire inflated','门把手松动时可拧紧固定螺丝。')]);
P('doric','Doric 源自拉丁语 Doricus、希腊语 Dorikos“多利安人的”；大写时多指古希腊多立克柱式，也可指苏格兰低地的 Doric 方言。',C('doric.s2','苏格兰语言','The novelist wrote the farm workers dialogue in Doric, using vocabulary associated with northeast Scotland.','小说家用 Doric 方言写农场工人的对白，采用与苏格兰东北部相关的词汇。','The novelist wrote the farm workers dialogue in Doric / using vocabulary / associated with northeast Scotland.','Doric 作名词可指苏格兰东北部方言，对应 s2。','地域词汇把对白标记为苏格兰东北方言。'),M('The architect described the Scottish dialect as Doric columns standing on a temple roof.','The architect described the temple columns as Doric, while the novelist used the Scottish Doric dialect.','方言和柱式是 Doric 的不同义项，不能混为同一物。','confusable'),[Q('doric',1,1,'A Doric column belongs to which tradition?','an ancient Greek architectural order','a modern computer network','a type of musical instrument','Doric 的建筑义是古希腊柱式之一。'),Q('doric',2,2,'Doric in a Scottish novel may refer to?','a dialect associated with northeast Scotland','the height of a Greek column','a form of ancient armor','苏格兰 Doric 指地方方言。'),Q('doric',3,1,'A building with simple heavy columns may be described as?','Doric','dormant','dorsal','Doric 可形容多立克柱式建筑。'),Q('doric',4,2,'Which sentence uses Doric for language?','The poet wrote in the Doric of the northeast.','The temple entrance has Doric columns.','The architect measured the column capital.','句中 poet wrote in the regional dialect。')]);
P('dorm','dorm 是 dormitory 的口语缩略形式；dormitory 源自拉丁语 dormitorium，与 dormire“睡觉”有关，指学生宿舍或集体寝室。',C('dorm.s1','校园生活','First-year students carried their boxes to the dorm and found their room assignments posted beside the entrance.','一年级学生把箱子搬到宿舍，并在入口旁看到房间分配表。','First-year students carried their boxes to the dorm / and found their room assignments / posted beside the entrance.','dorm 是 dormitory 的常用缩略名词；room in a dorm。','学生搬入集体宿舍，符合词义。'),M('The new student slept in a dorm that contained only one independent house and no shared rooms.','The new student slept in a private house rather than a dorm with shared student rooms.','dorm 指集体宿舍，不是独立私人住宅。','word-choice'),[Q('dorm',1,1,'A college dorm is a place where students?','live, often in shared residential rooms','take university entrance exams only','store cars during winter','dorm 是学生宿舍。'),Q('dorm',2,1,'A resident assistant in a dorm most likely helps?','students living in the residence hall','pilots navigate an airplane','patients choose a hospital surgeon','宿舍助理服务住在宿舍里的学生。'),Q('dorm',3,1,'Dorm is commonly short for?','dormitory','dormant','doormat','dorm 是 dormitory 的缩略。'),Q('dorm',4,1,'Which item would be typical in a dorm room?','a desk beside a student bed','a lighthouse lens','a tractor plow','学生宿舍通常有床和书桌。')]);
P('dormancy','dormancy 由 dormant 加 -cy 构成；dormant 源自拉丁语 dormire“睡觉”，表示暂时不活跃的状态，可用于生物休眠或疾病/风险潜伏。',C('dormancy.s2','疾病监测','The virus can remain in dormancy for years before symptoms appear, so patients still need follow-up care.','这种病毒可能潜伏多年才出现症状，因此患者仍需随访。','The virus can remain in dormancy for years / before symptoms appear / so patients still need follow-up care.','in dormancy 表示处于潜伏、不活动状态，对应 s2。','病原体暂时无症状但仍潜在，体现潜伏义。'),M('The virus was in dormancy because it was actively multiplying and causing severe symptoms every day.','The virus was active because it was multiplying and causing severe symptoms every day.','持续繁殖并每天引发症状表示活跃，不是 dormancy。','context'),[Q('dormancy',1,1,'A seed in dormancy is?','temporarily inactive and not yet growing','producing flowers at full speed','already turned into soil','dormancy 指休眠状态。'),Q('dormancy',2,2,'A disease in dormancy is?','present but inactive or hidden for a time','spreading rapidly with obvious symptoms','permanently cured in every case','疾病 dormancy 指潜伏、不活动。'),Q('dormancy',3,1,'Which phrase is natural?','a period of dormancy','a dormancy to bloom','dormancyly active','常见搭配 a period of dormancy。','collocation'),Q('dormancy',4,2,'A dormant risk that later becomes active was previously in?','dormancy','a full recovery','a permanent solution','潜在风险未发作时处于 dormancy。')]);
P('dorsal','dorsal 源自拉丁语 dorsalis“背部的”，来自 dorsum“背”；解剖学中指身体背侧，动物学中也用于背鳍等结构。',C('dorsal.s1','解剖与动物学','The shark raised its dorsal fin above the water as it turned toward the open sea.','鲨鱼转向外海时，把背鳍露出水面。','The shark raised its dorsal fin above the water / as it turned / toward the open sea.','dorsal fin 是固定搭配，指背鳍。','鳍位于鲨鱼背侧，符合 dorsal 的背部义。'),M('The dorsal fin was located under the shark beside its belly, not on its back.','The ventral fin was located under the shark beside its belly.','身体腹侧是 ventral；dorsal 指背侧。','confusable'),[Q('dorsal',1,1,'The dorsal side of an animal is its?','back side','belly side','left eye only','dorsal 指背侧。'),Q('dorsal',2,1,'A shark dorsal fin is located?','on its back','inside its stomach','on the underside of its tail only','背鳍位于背部。'),Q('dorsal',3,1,'Which term contrasts with dorsal in anatomy?','ventral','cranial','lateral','ventral 指腹侧，与背侧相对。'),Q('dorsal',4,1,'A dorsal view of a turtle shows it from?','above, looking at its back','underneath, looking at its belly','inside its shell','dorsal view 从背侧观察。')]);
P('dosage','dosage 由 dose 加名词后缀 -age 构成；dose 经法语来自希腊语 dosis“给予、剂量”，dosage 指药物的规定用量或剂量方案。',C('dosage.s1','用药安全','The pharmacist checked the dosage on the label and confirmed that the child should receive five milliliters twice a day.','药剂师核对标签上的用量，确认孩子应每天服用两次、每次五毫升。','The pharmacist checked the dosage on the label / and confirmed / that the child should receive five milliliters twice a day.','dosage 可指单次量或用药方案；计量单位须与药液匹配。','标签规定频次和体积，属于用药剂量。'),M('The bottle gave a dosage of five milliliters twice a day, but the caregiver administered five liters each time.','The bottle gave a dosage of five milliliters twice a day, and the caregiver measured the stated amount.','五升是严重偏离标签的用量，不能视作遵照剂量。','measurement'),[Q('dosage',1,1,'The dosage of a medicine is?','the amount and schedule to be taken','the color of its packaging','the name of the pharmacy','dosage 指药物用量/用药方案。'),Q('dosage',2,1,'A label says 2 tablets every 8 hours. This instruction gives the?','dosage','expiration date','manufacturer address','频次和数量共同构成剂量方案。'),Q('dosage',3,1,'Why should a patient follow the stated dosage?','to take a measured amount safely','to make the tablet change color','to guarantee the medicine tastes sweet','按规定剂量用药有助确保安全。'),Q('dosage',4,1,'Which is a dosage measurement?','10 milligrams once daily','a blue glass bottle','the pharmacy opening time','毫克数和频次是剂量信息。')]);
P('dote','dote 源自古英语 dotian“愚笨、失去理智”；现代常见结构 dote on 表示溺爱、宠爱某人，尤指老人过分宠爱。',C('dote.s1','家庭关系','Grandparents often dote on the youngest child, bringing her small gifts and praising every drawing she makes.','祖父母常常溺爱最小的孩子，给她带小礼物，并夸奖她画的每一幅画。','Grandparents often dote on the youngest child / bringing her small gifts / and praising every drawing she makes.','dote on + 人表示溺爱、宠爱；常用进行时描述持续行为。','不断送礼并过度夸奖体现宠爱。'),M('He doted to his grandchildren by showing them affection and buying them treats.','He doted on his grandchildren by showing them affection and buying them treats.','固定搭配是 dote on sb.，不是 dote to sb.','collocation'),[Q('dote',1,1,'To dote on a child is to?','show the child excessive affection or indulgence','ignore the child completely','teach the child a formal subject only','dote on 指溺爱、宠爱。'),Q('dote',2,1,'Which grandparent dotes on a grandchild?','one who constantly spoils and praises the child','one who never speaks to the child','one who forgets the child exists','过分宠爱、夸奖体现 dote on。'),Q('dote',3,1,'Complete the phrase: “She dotes ___ her grandson.”','on','at','from','正确介词搭配是 dote on。','collocation'),Q('dote',4,1,'Dote on is closest to?','be excessively fond of','be indifferent to','be formally employed by','dote on 表示非常宠爱。')]);
P('doubtless','doubtless 由 doubt 加 -less 构成；doubt 经古法语 douter 源自拉丁语 dubitare“迟疑”，副词可表示无疑地，形容词用法指毫无疑问的。',C('doubtless.s2','证据评估','Her account is doubtless accurate because three independent witnesses confirmed the same sequence of events.','她的叙述无疑是准确的，因为三名独立证人证实了相同的事件顺序。','Her account is doubtless accurate / because three independent witnesses / confirmed the same sequence of events.','doubtless 作表语形容词，常见结构 be doubtless that/about，对应 s2。','三名独立证人相互印证，使准确性毫无疑问。'),M('The evidence was doubtless because no one had checked it and every witness gave a different account.','The evidence was doubtful because no one had checked it and every witness gave a different account.','未核验且证词冲突使证据可疑，应为 doubtful。','word-choice'),[Q('doubtless',1,1,'Doubtless, the train will arrive on time means?','the speaker is certain it will arrive on time','the speaker has no idea whether it exists','the train has already been canceled','副词 doubtless 表示无疑地。'),Q('doubtless',2,2,'A claim that is doubtless is?','beyond reasonable doubt or certainly true','uncertain and unsupported','deliberately false','形容词义表示确定、毋庸置疑。'),Q('doubtless',3,1,'Which sentence uses the adverbial sense?','Doubtless, the new bridge will reduce travel time.','The doubtful bridge is doubtlessly made.','The bridge doubtlessly is a question mark.','句首副词表示“无疑地”。'),Q('doubtless',4,2,'Complete the adjective pattern: “She was ___ that the key was hers.”','doubtless','doubtlessly','doubt','be doubtless that... 可表示确信。','grammar')]);
P('dowdy','dowdy 是英语形容词，17世纪已有记录，指衣着或外表过时、土气、不整洁；它的更早词源不确定，不作未经证实的词根拆解。',C('dowdy.s1','服饰评论','The reviewer called the coat dowdy because its shapeless cut and faded trim looked decades out of date.','评论者称这件外套土气，因为无型的剪裁和褪色饰边显得过时几十年。','The reviewer called the coat dowdy / because its shapeless cut and faded trim / looked decades out of date.','dowdy 可形容衣服、外表或人，通常带贬义。','剪裁和饰边显得陈旧不时髦，符合 dowdy。'),M('She wore a dowdy, fashionable jacket that was newly designed and admired for its modern style.','She wore a stylish, fashionable jacket that was newly designed and admired for its modern style.','新潮且受赞赏的设计不应称 dowdy。','word-choice'),[Q('dowdy',1,1,'A dowdy outfit looks?','old-fashioned and unattractive','elegant and very fashionable','made for underwater use','dowdy 指土气、过时、不好看。'),Q('dowdy',2,1,'Which coat might be called dowdy?','a shapeless coat with faded trim from decades ago','a sleek new coat praised by fashion editors','a clean uniform worn for a ceremony','过时且无型的衣服符合 dowdy。'),Q('dowdy',3,1,'Dowdy is generally?','disapproving','a technical medical term','high praise','该词常带贬义。','register'),Q('dowdy',4,1,'The opposite of a dowdy appearance is?','stylish','frumpy','outdated','stylish 表示时髦，与土气过时相反。')]);
P('downcast','downcast 由 down 加 cast“投下”构成，字面为向下投；形容人时可指沮丧，也可描写目光朝下。',C('downcast.s2','肢体语言','When the teacher asked about the missing project, Eli kept his eyes downcast and avoided looking at his classmates.','老师询问失踪的项目时，伊莱垂下目光，避免看同学。','When the teacher asked about the missing project / Eli kept his eyes downcast / and avoided looking at his classmates.','eyes downcast 是固定描写，指目光低垂，对应 s2。','eyes 朝下且回避视线，体现目光低垂义。'),M('She stared straight ahead with eyes downcast toward the ceiling above the stage.','She stared straight ahead with eyes raised toward the ceiling above the stage.','直视天花板是抬眼，不是低垂目光。','context'),[Q('downcast',1,1,'A downcast person may feel?','sad or discouraged','triumphant','physically taller','downcast 常形容沮丧、气馁。'),Q('downcast',2,2,'Eyes downcast are?','directed toward the ground','fixed on the ceiling','closed permanently','s2 指目光低垂。'),Q('downcast',3,1,'The team looked downcast after?','losing the final despite months of training','winning the championship','receiving an unexpected holiday','失利后可能显得沮丧。'),Q('downcast',4,2,'Which gesture is downcast?','lowering one’s gaze while speaking','looking upward at a plane','turning one’s head toward a sound','低头向下看是 downcast eyes。')]);
P('downhearted','downhearted 由 down、heart 与 -ed 构成，形象地描写心情低落；可指沮丧，也可指无精打采。',C('downhearted.s2','身心状态','After a sleepless night caring for the baby, she felt downhearted and too tired to join the morning walk.','照顾婴儿熬了一夜后，她感到无精打采，累得无法参加晨间散步。','After a sleepless night caring for the baby / she felt downhearted / and too tired to join the morning walk.','downhearted 可表示无精打采、情绪低落；too tired to 表示太累而不能。','缺乏睡眠后疲惫低落，符合 s2 的无精打采义。'),M('He felt downhearted and energetic after sleeping well, cheering loudly and running all morning.','He felt refreshed and energetic after sleeping well, cheering loudly and running all morning.','精力充沛、兴奋活跃与 downhearted 的低落无力相反。','word-choice'),[Q('downhearted',1,1,'Someone who is downhearted feels?','sad or discouraged','confident and delighted','unable to recognize colors','downhearted 指沮丧、心情低落。'),Q('downhearted',2,2,'A downhearted worker who is exhausted may be?','low in spirits and lacking energy','full of energy and eager to run','angry about a spelling rule only','s2 还可表示无精打采。'),Q('downhearted',3,1,'Which event might leave a student downhearted?','a carefully prepared application is rejected','a scholarship is awarded unexpectedly','a long project is completed successfully','申请被拒可能令人沮丧。'),Q('downhearted',4,1,'The closest opposite of downhearted is?','cheerful and hopeful','discouraged','dejected','乐观愉快与垂头丧气相反。')]);
P('downhill','downhill 由 down 加 hill 构成；副词/形容词可指沿斜坡向下，也可比喻局势或健康状况开始变差。',C('downhill.s2','项目趋势','After the lead engineer resigned, the project went downhill: deadlines slipped, costs rose, and two key tests failed.','首席工程师辞职后，项目每况愈下：期限一再拖延，成本上升，两项关键测试也失败了。','After the lead engineer resigned / the project went downhill / deadlines slipped, costs rose, and two key tests failed.','go downhill 是状况恶化的常用比喻，对应 s2。','项目多项指标持续恶化，体现变差义。'),M('The project went downhill as every test passed, costs fell, and all deadlines were met early.','The project improved as every test passed, costs fell, and all deadlines were met early.','测试通过、成本下降且提前完成说明项目改善。','word-choice'),[Q('downhill',1,1,'To walk downhill is to walk?','down a slope','up a mountain','around a flat room','downhill 的字面义是沿坡向下。'),Q('downhill',2,2,'If a business goes downhill, it?','becomes worse or less successful','improves rapidly','moves to the top floor','go downhill 可比喻状况恶化。'),Q('downhill',3,1,'Which sentence uses downhill literally?','The cyclists raced downhill toward the village.','The company went downhill after losing its customers.','Her health went downhill over winter.','自行车沿坡向下是字面义。'),Q('downhill',4,2,'Which sentence uses the figurative sense?','After the repair, service quality went downhill.','They skied downhill on the marked trail.','The ball rolled downhill into the field.','服务质量变差使用比喻义。')]);
P('downright','downright 由 down 与 right 构成；可作副词表示彻底、十足，也可作形容词表示直率坦白，常用于强调评价。',C('downright.s2','人际沟通','Her downright answer surprised the panel: she said the proposal was unrealistic and explained exactly why.','她直率的回答让评审团吃惊：她说提案不现实，并准确解释了原因。','Her downright answer surprised the panel / she said the proposal was unrealistic / and explained exactly why.','downright 作形容词修饰 answer，突出直率坦白，对应 s2。','她不绕弯子地指出问题并给出理由，体现直率义。'),M('His downright answer avoided stating his view and hid every criticism behind vague hints.','His evasive answer avoided stating his view and hid every criticism behind vague hints.','含糊暗示、回避观点是 evasive，不是 downright 直率。','word-choice'),[Q('downright',1,1,'A downright unfair decision is?','completely or plainly unfair','only slightly unfair','fair in every respect','副词 downright 可强调“十足、完全”。'),Q('downright',2,2,'A downright speaker is?','frank and direct','evasive and vague','silent because of illness','形容词义可指直率坦白。'),Q('downright',3,1,'Which phrase uses downright as an intensifier?','downright dangerous behavior','downrightly the doorway','dangerously rightward speech','downright dangerous 意为十足危险。'),Q('downright',4,2,'A downright reply is most likely?','plainly expressed without evasive hints','hidden behind several layers of implication','a physical direction toward the right','downright reply 可指直截了当的回答。')]);
P('downsize','downsize 由 down 加 size 构成，20世纪后期成为商业用语，指缩小规模，尤其减少员工人数或缩减业务。',C('downsize.s1','企业调整','The retailer plans to downsize its regional office and transfer several support roles to a shared service center.','这家零售商计划缩减地区办公室规模，并把若干支持岗位转到共享服务中心。','The retailer plans to downsize its regional office / and transfer several support roles / to a shared service center.','downsize 可作及物或不及物动词；企业语境常与 office/workforce 连用。','办公室缩小并调整岗位，体现缩减规模义。'),M('The company downsized its workforce by hiring five hundred new employees and opening ten new offices.','The company expanded its workforce by hiring five hundred new employees and opening ten new offices.','大量招聘和开设新办公室是扩张，而非缩编。','word-choice'),[Q('downsize',1,1,'A company downsizes when it?','reduces the scale of its operations or workforce','opens many new branches and hires more staff','raises the size of every department','downsize 指缩小规模、常见为裁员缩编。'),Q('downsize',2,1,'A family may downsize a home by?','moving to a smaller house','adding several new floors','buying the largest available estate','downsizing 可指搬到更小的住宅。'),Q('downsize',3,1,'Which phrase is common in business?','downsize the workforce','downsize the employee into a desk','downsize for the profits workforce','downsize the workforce 是常见表达。','collocation'),Q('downsize',4,1,'If a firm downsizes after losing revenue, it may?','cut positions or close some offices','double every department','guarantee every role forever','缩编可能包括裁员或关闭办公室。')]);
})();
